window.PROMPTS=[{"id": "p-cap-1-1", "page": "cap-1", "pageTitle": "Email khó, viết lại trong 30 giây", "level": 1, "kind": "lesson", "code": "1a", "title": "Kiểu \"người lạ\"", "tags": ["chung"], "section": "Làm thật: từng bước", "text": "viết email trả lời khách về việc giao hàng chậm", "url": "cap-1.html#p-cap-1-1"}, {"id": "p-cap-1-2", "page": "cap-1", "pageTitle": "Email khó, viết lại trong 30 giây", "level": 1, "kind": "lesson", "code": "1b", "title": "Hỏi thẳng bạn ấy", "tags": ["chung"], "section": "Làm thật: từng bước", "text": "Mình cần trả lời một khách hàng lâu năm đang rất bực vì đơn hàng giao chậm. Bạn cần biết gì để viết email này thật tốt? Hỏi mình từng câu một nhé.", "url": "cap-1.html#p-cap-1-2"}, {"id": "p-cap-1-3", "page": "cap-1", "pageTitle": "Email khó, viết lại trong 30 giây", "level": 1, "kind": "lesson", "code": "1c", "title": "Nhờ góp ý thẳng", "tags": ["chung"], "section": "Làm thật: từng bước", "text": "Giờ bạn đóng vai người nhận, một người đang rất bực và khó tính. Đọc email này rồi nói thật 3 chỗ chưa ổn. Xong viết lại giúp mình.", "url": "cap-1.html#p-cap-1-3"}, {"id": "p-cap-1-4", "page": "cap-1", "pageTitle": "Email khó, viết lại trong 30 giây", "level": 1, "kind": "lesson", "code": "1d", "title": "Chốt bản cuối", "tags": ["chung"], "section": "Làm thật: từng bước", "text": "Ok, chốt giúp mình bản cuối: có tiêu đề, thân dưới 150 chữ, 2 phiên bản (trang trọng và thân thiện). Đánh dấu giúp mình những chỗ bạn tự thêm thông tin mà mình chưa nói.", "url": "cap-1.html#p-cap-1-4"}, {"id": "p-cap-1-5", "page": "cap-1", "pageTitle": "Email khó, viết lại trong 30 giây", "level": 1, "kind": "lesson", "code": "1e", "title": "Giao một lần cho trọn, như cho đồng nghiệp", "tags": ["chung", "kinhdoanh"], "section": "Làm thật: từng bước", "text": "Mình cần trả lời khách hàng [Công ty A], khách lâu năm, vừa phàn nàn vì đơn hàng giao chậm [5 ngày] do lỗi điều phối kho của bên mình. Họ đang rất bực, và mình muốn giữ khách.\nThế nào là tốt: xin lỗi cụ thể, không đổ lỗi, có giải pháp và mốc thời gian, đề xuất 1 ưu đãi bù đắp hợp lý. Có tiêu đề, thân dưới 150 chữ, 2 phiên bản (trang trọng / thân thiện).\nViệc này quan trọng, cứ làm kỹ.\nXong thì tự đọc lại như người nhận đang bực, sửa chỗ chưa ổn, và đánh dấu những chỗ bạn tự thêm mà mình chưa nói.\nThiếu gì quan trọng thì hỏi mình trước khi viết.", "url": "cap-1.html#p-cap-1-5"}, {"id": "p-cap-1-6", "page": "cap-1", "pageTitle": "Email khó, viết lại trong 30 giây", "level": 1, "kind": "lesson", "code": "1f", "title": "Soi chỗ bạn ấy tự thêm", "tags": ["chung"], "section": "Dám hỏi lại", "text": "Trong email này, liệt kê giúp mình mọi tên người, con số, ngày giờ, cam kết và ưu đãi. Cái nào là mình đã nói, cái nào là bạn tự thêm?", "url": "cap-1.html#p-cap-1-6"}, {"id": "p-cap-1-7", "page": "cap-1", "pageTitle": "Email khó, viết lại trong 30 giây", "level": 1, "kind": "lesson", "code": "1g", "title": "Công văn giải trình", "tags": ["luat"], "section": "Biến thể theo ngành", "text": "Công ty mình vừa nhận công văn của [cơ quan] yêu cầu giải trình về [vấn đề] trong 10 ngày. Mình cần soạn công văn trả lời, chặt chẽ, đúng thể thức, không thừa nhận quá những gì đã xảy ra. Bạn cần biết gì thì hỏi mình từng câu một nhé.", "url": "cap-1.html#p-cap-1-7"}, {"id": "p-cap-1-8", "page": "cap-1", "pageTitle": "Email khó, viết lại trong 30 giây", "level": 1, "kind": "lesson", "code": "1h", "title": "Nhắc nợ lần 2", "tags": ["ketoan"], "section": "Biến thể theo ngành", "text": "Khách hàng [B] quá hạn thanh toán 45 ngày, mình đã nhắc 1 lần qua email. Mình cần email nhắc lần 2, lịch sự mà cương quyết, nêu rõ bước tiếp theo nếu vẫn chưa thanh toán. Hỏi mình từng câu một trước khi viết nhé.", "url": "cap-1.html#p-cap-1-8"}, {"id": "p-cap-1-9", "page": "cap-1", "pageTitle": "Email khó, viết lại trong 30 giây", "level": 1, "kind": "lesson", "code": "1i", "title": "Từ chối giảm giá khéo léo", "tags": ["kinhdoanh"], "section": "Biến thể theo ngành", "text": "Khách hỏi giảm giá 15% nhưng mình chỉ được duyệt tối đa 5%. Mình cần trả lời khéo để không mất khách, có thể đề xuất thứ khác thay cho giảm giá. Bạn cần biết gì về khách và đơn hàng thì hỏi mình nhé.", "url": "cap-1.html#p-cap-1-9"}, {"id": "p-cap-1-10", "page": "cap-1", "pageTitle": "Email khó, viết lại trong 30 giây", "level": 1, "kind": "lesson", "code": "1j", "title": "Thông báo dừng thang máy", "tags": ["vanhanh"], "section": "Biến thể theo ngành", "text": "Thang máy block B phải dừng bảo trì 2 ngày. Mình cần thông báo gửi cư dân: ngắn, dễ hiểu, có thời gian cụ thể, phương án hỗ trợ người già và trẻ nhỏ, số liên hệ khi cần. Hỏi mình những gì còn thiếu rồi viết nhé. Xong đóng vai một cư dân khó tính góp ý luôn.", "url": "cap-1.html#p-cap-1-10"}, {"id": "p-cap-2-1", "page": "cap-2", "pageTitle": "Tài liệu dài, và bẫy “AI bịa”", "level": 2, "kind": "lesson", "code": "2a", "title": "Tóm tắt theo góc nhìn bên mua", "tags": ["luat", "chung"], "section": "Làm thật: từng bước", "text": "Mình là bên mua. Tóm tắt giúp mình hợp đồng này nhé. Mình cần biết: ai phải làm gì, hạn khi nào, và chỗ nào bất lợi hoặc viết mơ hồ cho mình.", "url": "cap-2.html#p-cap-2-1"}, {"id": "p-cap-2-2", "page": "cap-2", "pageTitle": "Tài liệu dài, và bẫy “AI bịa”", "level": 2, "kind": "lesson", "code": "2-bẫy", "title": "Thử bắt bạn ấy đoán", "tags": ["chung"], "section": "Làm thật: từng bước", "text": "Nếu bên bán giao hàng chậm thì bị phạt bao nhiêu tiền?", "url": "cap-2.html#p-cap-2-2"}, {"id": "p-cap-2-3", "page": "cap-2", "pageTitle": "Tài liệu dài, và bẫy “AI bịa”", "level": 2, "kind": "lesson", "code": "2b", "title": "Hỏi thẳng bạn ấy", "tags": ["meta", "chung"], "section": "Làm thật: từng bước", "text": "Làm sao để mình biết bạn không bịa? Bạn gợi ý cách để mình kiểm tra câu trả lời của bạn đi.", "url": "cap-2.html#p-cap-2-3"}, {"id": "p-cap-2-4", "page": "cap-2", "pageTitle": "Tài liệu dài, và bẫy “AI bịa”", "level": 2, "kind": "lesson", "code": "2c", "title": "Trích nguyên văn kèm số Điều", "tags": ["chung"], "section": "Làm thật: từng bước", "text": "Ok, làm đúng như bạn vừa nói nhé: với mỗi ý, trích nguyên văn câu trong tài liệu kèm số Điều (hoặc số trang). Chỗ nào là bạn suy luận thì nói rõ.", "url": "cap-2.html#p-cap-2-4"}, {"id": "p-cap-2-5", "page": "cap-2", "pageTitle": "Tài liệu dài, và bẫy “AI bịa”", "level": 2, "kind": "lesson", "code": "2d", "title": "Hỏi lại câu bẫy với luật chơi mới", "tags": ["chung"], "section": "Làm thật: từng bước", "text": "Giờ trả lời lại câu lúc nãy theo đúng cách đó: nếu bên bán giao hàng chậm thì bị phạt bao nhiêu? Chỉ dùng thông tin trong hợp đồng, trích nguyên văn. Hợp đồng không nói thì nói là không có.", "url": "cap-2.html#p-cap-2-5"}, {"id": "p-cap-2-6", "page": "cap-2", "pageTitle": "Tài liệu dài, và bẫy “AI bịa”", "level": 2, "kind": "lesson", "code": "2e", "title": "Khi trích dẫn không khớp", "tags": ["chung"], "section": "Làm thật: từng bước", "text": "Câu bạn trích ở Điều [số] không khớp với file của mình. Trong file ghi: \"[dán câu gốc]\". Kiểm tra lại toàn bộ các trích dẫn khác và sửa những chỗ sai giúp mình.", "url": "cap-2.html#p-cap-2-6"}, {"id": "p-cap-2-7", "page": "cap-2", "pageTitle": "Tài liệu dài, và bẫy “AI bịa”", "level": 2, "kind": "lesson", "code": "2f", "title": "Hỏi trong NotebookLM", "tags": ["luat", "chung"], "section": "Làm thật: từng bước", "text": "Mình là bên mua. Liệt kê các điều khoản bất lợi cho mình. Nếu bên bán giao hàng chậm thì bị phạt bao nhiêu?", "url": "cap-2.html#p-cap-2-7"}, {"id": "p-cap-2-8", "page": "cap-2", "pageTitle": "Tài liệu dài, và bẫy “AI bịa”", "level": 2, "kind": "lesson", "code": "2g", "title": "So sánh hai phiên bản văn bản", "tags": ["luat"], "section": "Biến thể theo ngành", "text": "Mình gửi bạn 2 file: bản cũ và bản mới của [văn bản / hợp đồng]. Điểm nào mới, điểm nào bị bỏ, điểm nào sửa câu chữ làm đổi nghĩa? Với mỗi điểm, trích nguyên văn cả bản cũ và bản mới kèm số Điều.", "url": "cap-2.html#p-cap-2-8"}, {"id": "p-cap-2-9", "page": "cap-2", "pageTitle": "Tài liệu dài, và bẫy “AI bịa”", "level": 2, "kind": "lesson", "code": "2h", "title": "Đọc nhanh báo cáo tài chính", "tags": ["ketoan"], "section": "Biến thể theo ngành", "text": "Đây là báo cáo tài chính [kỳ này] (đã che tên công ty). Khoản mục nào thay đổi nhiều nhất so với kỳ trước, vì sao? Với mỗi con số, ghi rõ lấy từ bảng nào, dòng nào để mình đối chiếu. Phần trăm thay đổi thì ghi luôn cách tính.", "url": "cap-2.html#p-cap-2-9"}, {"id": "p-cap-2-10", "page": "cap-2", "pageTitle": "Tài liệu dài, và bẫy “AI bịa”", "level": 2, "kind": "lesson", "code": "2i", "title": "Đọc hồ sơ mời thầu", "tags": ["kinhdoanh"], "section": "Biến thể theo ngành", "text": "Đây là hồ sơ mời thầu. Liệt kê giúp mình: các yêu cầu bắt buộc (không đáp ứng là bị loại), hạn nộp và các mốc thời gian, những điểm công ty mình có thể yếu. Mỗi ý trích nguyên văn kèm số mục hoặc số trang.", "url": "cap-2.html#p-cap-2-10"}, {"id": "p-cap-2-11", "page": "cap-2", "pageTitle": "Tài liệu dài, và bẫy “AI bịa”", "level": 2, "kind": "lesson", "code": "2j", "title": "Rà nghĩa vụ trong hợp đồng thi công", "tags": ["vanhanh"], "section": "Biến thể theo ngành", "text": "Mình là bên [nhà thầu / chủ đầu tư]. Đọc hợp đồng thi công này, lập bảng: nghĩa vụ của bên mình, mốc thời gian, điều kiện nghiệm thu, mức phạt nếu chậm. Mỗi dòng trích nguyên văn kèm số Điều. Chỗ nào hợp đồng không nói rõ thì ghi \"không quy định\".", "url": "cap-2.html#p-cap-2-11"}, {"id": "p-cap-2-12", "page": "cap-2", "pageTitle": "Tài liệu dài, và bẫy “AI bịa”", "level": 2, "kind": "lesson", "code": "2k", "title": "Luật chơi khi đọc tài liệu", "tags": ["meta", "chung"], "section": "Đi xa hơn", "text": "Trong cuộc trò chuyện này, chỉ dùng thông tin trong tài liệu mình gửi. Mỗi ý trích nguyên văn kèm số Điều hoặc số trang. Chỗ nào là suy luận thì ghi rõ \"suy luận\". Tài liệu không nói thì trả lời \"không có trong tài liệu\", đừng đoán.", "url": "cap-2.html#p-cap-2-12"}, {"id": "p-cap-3-1", "page": "cap-3", "pageTitle": "Excel lộn xộn thành sạch", "level": 3, "kind": "lesson", "code": "3a", "title": "Hỏi thẳng bạn ấy", "tags": ["chung", "ketoan"], "section": "Làm thật: từng bước", "text": "File này lộn xộn quá, mình cũng chưa biết nên làm gì với nó. Bạn xem qua rồi gợi ý 5 việc bạn có thể làm giúp mình nhé.", "url": "cap-3.html#p-cap-3-1"}, {"id": "p-cap-3-2", "page": "cap-3", "pageTitle": "Excel lộn xộn thành sạch", "level": 3, "kind": "lesson", "code": "3b", "title": "Dọn, phân nhóm, tổng hợp, cho tải file", "tags": ["chung", "ketoan"], "section": "Làm thật: từng bước", "text": "Làm hết mấy việc đó giúp mình nhé. Cụ thể:\n1. Bỏ dòng trùng (dòng giống hệt nhau ở mọi cột).\n2. Đưa cột Ngày về một định dạng ngày/tháng/năm. Tất cả đều là tháng 9/2026.\n3. Thống nhất tên nhà cung cấp, mỗi nơi một tên chuẩn.\n4. Đổi số tiền gõ dạng chữ thành số.\n5. Ô trống thì ghi \"Chưa rõ\", đừng tự điền.\n6. Thêm cột Nhóm chi phí với 5 nhóm: Văn phòng phẩm, Đi lại, Tiếp khách, Dịch vụ thuê ngoài, Khác.\nSau đó tổng hợp theo nhóm và theo tuần (tuần tính từ thứ Hai đến Chủ nhật), vẽ biểu đồ, và cho mình tải file Excel đã làm sạch. Làm xong thì liệt kê ngắn những gì bạn đã sửa, mỗi loại bao nhiêu dòng.", "url": "cap-3.html#p-cap-3-2"}, {"id": "p-cap-3-3", "page": "cap-3", "pageTitle": "Excel lộn xộn thành sạch", "level": 3, "kind": "lesson", "code": "3c", "title": "Giải thích 3 dòng và cách tính", "tags": ["chung", "ketoan"], "section": "Làm thật: từng bước", "text": "Chọn ngẫu nhiên 3 dòng trong file gốc, cho mình biết số thứ tự dòng, rồi giải thích từng dòng: bạn đã sửa gì, xếp vào nhóm nào và vì sao. Chỉ luôn cho mình cách bạn tính tổng của nhóm Tiếp khách.", "url": "cap-3.html#p-cap-3-3"}, {"id": "p-cap-3-4", "page": "cap-3", "pageTitle": "Excel lộn xộn thành sạch", "level": 3, "kind": "lesson", "code": "3d", "title": "Chỉ cách tự kiểm trong Excel", "tags": ["chung", "ketoan"], "section": "Làm thật: từng bước", "text": "Mình đã tải file về. Chỉ mình cách tự kiểm tra trong Excel trong 2 phút: đếm số dòng, tính lại tổng tiền, và lọc xem tên nhà cung cấp đã thống nhất chưa. Hướng dẫn từng bước, nói rõ bấm vào đâu.", "url": "cap-3.html#p-cap-3-4"}, {"id": "p-cap-3-5", "page": "cap-3", "pageTitle": "Excel lộn xộn thành sạch", "level": 3, "kind": "lesson", "code": "3e", "title": "Viết công thức và giải thích bằng tiếng Việt", "tags": ["ketoan", "chung"], "section": "Làm thật: từng bước", "text": "Bảng của mình: cột A mã khách hàng, cột B ngày hoá đơn, cột C số tiền, cột D ngày đã trả (trống nếu chưa trả). Dữ liệu từ dòng 2 đến dòng 26. Hạn trả là 30 ngày kể từ ngày hoá đơn.\nMình muốn cột E tính số ngày quá hạn (khoản chưa trả thì tính đến hôm nay, khoản đã trả thì để 0), cột F ghi \"Đã trả\", \"Quá hạn\" hoặc \"Trong hạn\".\nViết công thức giúp mình, giải thích từng phần thật dễ hiểu. Excel của mình dùng dấu \";\".", "url": "cap-3.html#p-cap-3-5"}, {"id": "p-cap-3-6", "page": "cap-3", "pageTitle": "Excel lộn xộn thành sạch", "level": 3, "kind": "lesson", "code": "3f", "title": "Hỏi lại dòng trùng và tổng tiền", "tags": ["chung", "ketoan"], "section": "Dám hỏi lại", "text": "Bạn tìm được bao nhiêu dòng trùng? Liệt kê số thứ tự các dòng đó trong file gốc. Tổng chi phí sau khi bỏ trùng là bao nhiêu? Có dòng nào số tiền không phải dạng số không, bạn xử lý chúng thế nào?", "url": "cap-3.html#p-cap-3-6"}, {"id": "p-cap-3-7", "page": "cap-3", "pageTitle": "Excel lộn xộn thành sạch", "level": 3, "kind": "lesson", "code": "3g", "title": "Dọn danh sách hồ sơ vụ việc", "tags": ["luat"], "section": "Biến thể theo ngành", "text": "Đây là danh sách hồ sơ vụ việc (đã thay tên khách hàng bằng mã). Bạn xem rồi gợi ý cách sắp xếp lại cho dễ theo dõi. Sau đó đánh dấu giúp mình những hồ sơ còn dưới 7 ngày là đến hạn, và giải thích bạn tính hạn thế nào.", "url": "cap-3.html#p-cap-3-7"}, {"id": "p-cap-3-8", "page": "cap-3", "pageTitle": "Excel lộn xộn thành sạch", "level": 3, "kind": "lesson", "code": "3h", "title": "Phân loại sao kê ngân hàng", "tags": ["ketoan"], "section": "Biến thể theo ngành", "text": "Đây là sao kê tài khoản tháng [9] tải từ ngân hàng (mình đã xoá số tài khoản). Phân loại các khoản thu chi theo nhóm hợp lý, tổng hợp theo nhóm, đánh dấu các khoản bất thường. Chọn 3 dòng giải thích cách bạn phân loại để mình kiểm tra.", "url": "cap-3.html#p-cap-3-8"}, {"id": "p-cap-3-9", "page": "cap-3", "pageTitle": "Excel lộn xộn thành sạch", "level": 3, "kind": "lesson", "code": "3i", "title": "Ai là khách hàng quan trọng nhất?", "tags": ["kinhdoanh"], "section": "Biến thể theo ngành", "text": "Đây là danh sách đơn hàng 3 tháng gần nhất. Gộp những tên khách hàng bị viết khác nhau, rồi cho mình biết: top 10 khách hàng theo doanh số, và những khách đang mua ít đi so với tháng trước. Nói rõ cách bạn tính.", "url": "cap-3.html#p-cap-3-9"}, {"id": "p-cap-3-10", "page": "cap-3", "pageTitle": "Excel lộn xộn thành sạch", "level": 3, "kind": "lesson", "code": "3j", "title": "Phân tích nhật ký sự cố", "tags": ["vanhanh"], "section": "Biến thể theo ngành", "text": "Đây là nhật ký sự cố bảo trì 6 tháng. Chuẩn hoá tên hạng mục, rồi cho mình biết: hạng mục nào hỏng nhiều nhất, thời gian xử lý trung bình bao lâu, tháng nào nhiều sự cố nhất. Vẽ biểu đồ và cho mình tải file đã làm sạch.", "url": "cap-3.html#p-cap-3-10"}, {"id": "p-cap-4-1", "page": "cap-4", "pageTitle": "Số liệu thành báo cáo thành slide", "level": 4, "kind": "lesson", "code": "4a", "title": "Nói tiếp từ bậc 3", "tags": ["chung"], "section": "Làm thật: từng bước", "text": "Mình nói tiếp nhé. Trước khi làm báo cáo, bạn nhắc lại giúp mình: tổng chi phí tháng 9 sau khi bỏ dòng trùng, chi phí theo 5 nhóm (số tiền và tỷ trọng), và chi phí theo từng tuần. Trình bày thành 2 bảng gọn.", "url": "cap-4.html#p-cap-4-1"}, {"id": "p-cap-4-2", "page": "cap-4", "pageTitle": "Số liệu thành báo cáo thành slide", "level": 4, "kind": "lesson", "code": "4b", "title": "Số liệu mẫu nếu bạn bỏ qua bậc 3", "tags": ["chung", "ketoan"], "section": "Làm thật: từng bước", "text": "Đây là chi phí tháng 9/2026 của công ty mình (đã làm sạch, bỏ 8 dòng trùng). Tổng: 384.070.000đ.\n\nTheo nhóm:\n- Văn phòng phẩm: 48.279.000đ (12,6%)\n- Đi lại: 30.258.000đ (7,9%)\n- Tiếp khách: 121.722.000đ (31,7%)\n- Dịch vụ thuê ngoài: 134.183.000đ (34,9%)\n- Khác: 49.628.000đ (12,9%)\n\nTheo tuần:\n- Tuần 1 (01–06/9): 81.144.000đ\n- Tuần 2 (07–13/9): 63.442.000đ\n- Tuần 3 (14–20/9): 80.467.000đ\n- Tuần 4 (21–27/9): 123.521.000đ\n- Tuần 5 (28–30/9): 35.496.000đ\n\nBạn đọc kỹ rồi nói cho mình 3 điều đáng chú ý nhất trong số liệu này nhé. Chưa cần viết báo cáo.", "url": "cap-4.html#p-cap-4-2"}, {"id": "p-cap-4-3", "page": "cap-4", "pageTitle": "Số liệu thành báo cáo thành slide", "level": 4, "kind": "lesson", "code": "4c", "title": "Hỏi thẳng bạn ấy", "tags": ["chung"], "section": "Làm thật: từng bước", "text": "Giờ mình cần báo cáo kết quả này lên Giám đốc. Trước khi viết, bạn hỏi mình 3 câu về sếp và cuộc họp để viết cho hợp gu nhé. Hỏi từng câu một.", "url": "cap-4.html#p-cap-4-3"}, {"id": "p-cap-4-4", "page": "cap-4", "pageTitle": "Số liệu thành báo cáo thành slide", "level": 4, "kind": "lesson", "code": "4d", "title": "Viết báo cáo một trang", "tags": ["chung", "ketoan"], "section": "Làm thật: từng bước", "text": "Dựa trên số liệu và những gì mình vừa kể về sếp, viết giúp mình báo cáo chi phí tháng 9 gửi Giám đốc, gói gọn trong 1 trang:\n1. Tóm tắt cho lãnh đạo: đúng 3 câu.\n2. Ba phát hiện chính, mỗi phát hiện có con số cụ thể.\n3. Hai việc đề xuất, có người phụ trách và thời hạn (chỗ nào chưa biết thì để [ngoặc vuông] cho mình điền).\nChỉ dùng số liệu có trong cuộc trò chuyện này. Con số nào bạn tự tính thêm thì ghi rõ cách tính.", "url": "cap-4.html#p-cap-4-4"}, {"id": "p-cap-4-5", "page": "cap-4", "pageTitle": "Số liệu thành báo cáo thành slide", "level": 4, "kind": "lesson", "code": "4e", "title": "Sếp khó tính vặn trước", "tags": ["chung"], "section": "Làm thật: từng bước", "text": "Giờ bạn đóng vai Giám đốc tài chính rất khó tính, nổi tiếng hay vặn số liệu. Đọc báo cáo trên rồi hỏi mình 3 câu khó nhất mà ông ấy có thể hỏi trong cuộc họp. Chưa cần trả lời.", "url": "cap-4.html#p-cap-4-5"}, {"id": "p-cap-4-6", "page": "cap-4", "pageTitle": "Số liệu thành báo cáo thành slide", "level": 4, "kind": "lesson", "code": "4f", "title": "Sửa báo cáo để trả lời trước", "tags": ["chung"], "section": "Làm thật: từng bước", "text": "Cảm ơn bạn. Giờ quay lại vai người viết, sửa báo cáo để trả lời trước cả 3 câu đó ngay trong bài, vẫn gói trong 1 trang. Câu nào chưa đủ số liệu để trả lời thì ghi rõ \"cần bổ sung\" và gợi ý mình nên lấy số liệu đó ở đâu.", "url": "cap-4.html#p-cap-4-6"}, {"id": "p-cap-4-7", "page": "cap-4", "pageTitle": "Số liệu thành báo cáo thành slide", "level": 4, "kind": "lesson", "code": "4g", "title": "Biến thành slide", "tags": ["chung"], "section": "Làm thật: từng bước", "text": "Biến báo cáo vừa sửa thành bài trình chiếu 6 slide dạng trang web: chữ to dễ đọc, gọn và đẹp, có biểu đồ chi phí theo nhóm và theo tuần, có nút chuyển slide và dùng được phím mũi tên. Toàn bộ bằng tiếng Việt. Slide cuối là 2 đề xuất cần sếp quyết định.", "url": "cap-4.html#p-cap-4-7"}, {"id": "p-cap-4-8", "page": "cap-4", "pageTitle": "Số liệu thành báo cáo thành slide", "level": 4, "kind": "lesson", "code": "4h", "title": "Dàn ý slide cho PowerPoint", "tags": ["chung"], "section": "Làm thật: từng bước", "text": "Viết giúp mình dàn ý 6 slide cho PowerPoint từ báo cáo này. Mỗi slide gồm: tiêu đề dưới 10 chữ, 3–4 gạch đầu dòng ngắn, gợi ý loại biểu đồ nếu cần (kèm số liệu để mình tự vẽ), và 2–3 câu ghi chú để mình nói khi trình bày.", "url": "cap-4.html#p-cap-4-8"}, {"id": "p-cap-4-9", "page": "cap-4", "pageTitle": "Số liệu thành báo cáo thành slide", "level": 4, "kind": "lesson", "code": "4i", "title": "Hỏi cách mang slide đi họp", "tags": ["chung"], "section": "Làm thật: từng bước", "text": "Mình cần chiếu bộ slide này trên máy phòng họp và gửi sếp một bản PDF. Với công cụ mình đang dùng, cách nào đơn giản nhất? Hướng dẫn mình từng bước, như hướng dẫn người không rành máy tính.", "url": "cap-4.html#p-cap-4-9"}, {"id": "p-cap-4-10", "page": "cap-4", "pageTitle": "Số liệu thành báo cáo thành slide", "level": 4, "kind": "lesson", "code": "4j", "title": "Rà nguồn từng con số", "tags": ["chung"], "section": "Dám hỏi lại", "text": "Rà lại giúp mình: liệt kê mọi con số xuất hiện trong báo cáo và trên slide, ghi bên cạnh nguồn của nó (bảng nào phía trên, hay do bạn tính). Số nào do bạn tính thì ghi phép tính. Câu nào là nhận định của bạn chứ không phải dữ liệu thì đánh dấu.", "url": "cap-4.html#p-cap-4-10"}, {"id": "p-cap-4-11", "page": "cap-4", "pageTitle": "Số liệu thành báo cáo thành slide", "level": 4, "kind": "lesson", "code": "4k", "title": "Từ rà soát hợp đồng đến memo", "tags": ["luat"], "section": "Biến thể theo ngành", "text": "Từ các điểm bất lợi bạn vừa tìm trong hợp đồng, viết giúp mình memo 1 trang gửi Ban Giám đốc: 3 rủi ro lớn nhất (kèm số Điều), mức độ rủi ro, đề xuất đàm phán lại từng điểm. Trước khi viết, hỏi mình 2 câu về người sẽ quyết định ký hợp đồng này. Xong làm 4 slide cho buổi họp duyệt ký.", "url": "cap-4.html#p-cap-4-11"}, {"id": "p-cap-4-12", "page": "cap-4", "pageTitle": "Số liệu thành báo cáo thành slide", "level": 4, "kind": "lesson", "code": "4l", "title": "Báo cáo tuổi nợ", "tags": ["ketoan"], "section": "Biến thể theo ngành", "text": "Từ bảng công nợ mình vừa làm, chia khách hàng thành các nhóm: trong hạn, quá hạn 1–30 ngày, 31–60 ngày, trên 60 ngày. Viết báo cáo 1 trang gửi Kế toán trưởng: tổng nợ từng nhóm, 3 khách cần ưu tiên thu hồi, 2 đề xuất. Sau đó làm 4 slide có biểu đồ tuổi nợ.", "url": "cap-4.html#p-cap-4-12"}, {"id": "p-cap-4-13", "page": "cap-4", "pageTitle": "Số liệu thành báo cáo thành slide", "level": 4, "kind": "lesson", "code": "4m", "title": "Doanh số tháng thành bài họp sales", "tags": ["kinhdoanh"], "section": "Biến thể theo ngành", "text": "Đây là bảng doanh số tháng [tháng] theo nhân viên và khách hàng (đã che tên khách): [dán bảng]. Hỏi mình 3 câu về buổi họp sales sáng thứ Hai, rồi viết báo cáo 1 trang: ai vượt chỉ tiêu, khách nào mua ít đi, 2 việc cả nhóm cần làm tuần này. Xong làm 5 slide thật có năng lượng để mở đầu buổi họp.", "url": "cap-4.html#p-cap-4-13"}, {"id": "p-cap-4-14", "page": "cap-4", "pageTitle": "Số liệu thành báo cáo thành slide", "level": 4, "kind": "lesson", "code": "4n", "title": "Nhật ký bảo trì thành báo cáo quý", "tags": ["vanhanh"], "section": "Biến thể theo ngành", "text": "Đây là nhật ký sự cố bảo trì quý [quý]: [dán bảng]. Tìm 3 hạng mục hỏng nhiều nhất, thời gian xử lý trung bình, chi phí từng hạng mục. Viết báo cáo 1 trang gửi Ban quản lý, có 2 đề xuất thay thế hoặc bảo dưỡng định kỳ. Rồi đóng vai trưởng ban quản lý khó tính, vặn mình 3 câu.", "url": "cap-4.html#p-cap-4-14"}, {"id": "p-cap-5-1", "page": "cap-5", "pageTitle": "Trợ lý biết nhớ việc", "level": 5, "kind": "lesson", "code": "5a", "title": "Hỏi về góc làm việc riêng", "tags": ["meta"], "section": "Làm thật: từng bước", "text": "Mình muốn tạo một \"góc làm việc riêng\" để bạn nhớ hướng dẫn và tài liệu của mình (kiểu Project hoặc Gem). Với công cụ mình đang dùng, tính năng đó tên là gì, nằm ở đâu, các bước tạo ra sao? Nếu bạn không chắc giao diện hiện tại, cứ nói thật để mình tự kiểm tra.", "url": "cap-5.html#p-cap-5-1"}, {"id": "p-cap-5-2", "page": "cap-5", "pageTitle": "Trợ lý biết nhớ việc", "level": 5, "kind": "lesson", "code": "5b", "title": "Phỏng vấn rồi tự viết hướng dẫn", "tags": ["meta", "chung"], "section": "Làm thật: từng bước", "text": "Mình muốn tạo một trợ lý nhớ cách mình làm báo cáo tuần. Bạn phỏng vấn mình từng câu một: mình là ai, làm việc này thế nào, thích kết quả ra sao, điều gì tuyệt đối không được làm. Hỏi đủ thì dừng, rồi tự viết giúp mình phần hướng dẫn để dán vào Project. Viết ngắn gọn, rõ ràng, dưới 300 chữ.", "url": "cap-5.html#p-cap-5-2"}, {"id": "p-cap-5-3", "page": "cap-5", "pageTitle": "Trợ lý biết nhớ việc", "level": 5, "kind": "lesson", "code": "5c", "title": "Kiểm tra bạn ấy đã học bài", "tags": ["meta"], "section": "Làm thật: từng bước", "text": "Trước khi làm việc, bạn cho mình biết: bạn hiểu mình sẽ nhờ bạn làm gì? Mẫu báo cáo có những mục nào? Giọng văn bạn rút ra từ 2 báo cáo cũ ra sao? Có điều gì trong hướng dẫn bạn thấy chưa rõ không?", "url": "cap-5.html#p-cap-5-3"}, {"id": "p-cap-5-4", "page": "cap-5", "pageTitle": "Trợ lý biết nhớ việc", "level": 5, "kind": "lesson", "code": "5d", "title": "Số liệu tuần 40", "tags": ["chung", "kinhdoanh"], "section": "Làm thật: từng bước", "text": "Số liệu tuần 40:\nso lieu tuan 40 (28/9 - 4/10) - Ha ghi vội\n- ds tuan nay ~1,29 ty (CHUA tinh don truong Hoa Sen 85tr dang cho xuat hd)\n- don: 44 / kh moi: 7 (2 truong hoc, 1 van phong luat, con lai le)\n- thu no dc 1,02 ty. Phuc Loc tra them 40tr, con 80tr, qua han 40 ngay roi\n- Minh Quang: KH doi thong so ban hop LAN 2 -> bao gia lui sang 9/10, Quan phu trach\n- doi thu giam gia giay A4 tong ~5%, tuan nay mat 1 khach le vi gia\n- sep hoi ve combo giay + muc -> chua co quyet dinh\n- tuan sau: chot Hoa Sen, gui bao gia Minh Quang, hop voi Phuc Loc, chuan bi hoi cho VPP thang 10", "url": "cap-5.html#p-cap-5-4"}, {"id": "p-cap-5-5", "page": "cap-5", "pageTitle": "Trợ lý biết nhớ việc", "level": 5, "kind": "lesson", "code": "5e", "title": "Dạy thêm một điều", "tags": ["meta"], "section": "Làm thật: từng bước", "text": "Báo cáo ổn rồi, nhưng từ nay mình muốn [phần Tóm tắt luôn mở đầu bằng % kế hoạch doanh số / mục Rủi ro xếp từ mức độ cao xuống thấp]. Viết lại toàn bộ phần hướng dẫn, đã thêm điều này, để mình dán đè vào Project.", "url": "cap-5.html#p-cap-5-5"}, {"id": "p-cap-5-6", "page": "cap-5", "pageTitle": "Trợ lý biết nhớ việc", "level": 5, "kind": "lesson", "code": "5f", "title": "Gợi ý trợ lý cho riêng mình", "tags": ["meta", "doisong"], "section": "Làm thật: từng bước", "text": "Mình làm [nghề, vị trí]. Mỗi tuần mình hay lặp lại những việc như [kể 3–4 việc]. Ở nhà, mình [kể chút về gia đình, sở thích, việc hay phải lo]. Gợi ý cho mình 5 trợ lý nên tạo bằng Project hoặc Gem, mỗi trợ lý ghi: tên, việc nó làm, cần tải lên tài liệu gì, và câu mở lời mỗi lần dùng.", "url": "cap-5.html#p-cap-5-6"}, {"id": "p-cap-5-7", "page": "cap-5", "pageTitle": "Trợ lý biết nhớ việc", "level": 5, "kind": "lesson", "code": "5g", "title": "Hỏi nguồn từng con số", "tags": ["chung"], "section": "Dám hỏi lại", "text": "Với mỗi con số trong báo cáo, ghi giúp mình nó lấy từ đâu: từ ghi chú tuần 40 mình vừa dán, từ báo cáo tuần trước trong phần tệp, hay do bạn tự tính. Số nào tự tính thì ghi phép tính.", "url": "cap-5.html#p-cap-5-7"}, {"id": "p-cap-5-8", "page": "cap-5", "pageTitle": "Trợ lý biết nhớ việc", "level": 5, "kind": "lesson", "code": "5h", "title": "Trợ lý rà soát hợp đồng", "tags": ["luat"], "section": "Biến thể theo ngành", "text": "Mình muốn tạo một trợ lý pháp chế rà soát hợp đồng mua bán theo đúng checklist của công ty (mình sẽ tải lên checklist và 2 hợp đồng mẫu đã che tên). Phỏng vấn mình từng câu: công ty thường ở vị thế bên mua hay bên bán, điều khoản nào bắt buộc phải có, rủi ro mức nào phải báo sếp, trình bày kết quả ra sao. Xong viết hướng dẫn cho Project, có yêu cầu trích số Điều cho mọi nhận xét.", "url": "cap-5.html#p-cap-5-8"}, {"id": "p-cap-5-9", "page": "cap-5", "pageTitle": "Trợ lý biết nhớ việc", "level": 5, "kind": "lesson", "code": "5i", "title": "Trợ lý báo cáo tháng", "tags": ["ketoan"], "section": "Biến thể theo ngành", "text": "Mình muốn tạo trợ lý viết thuyết minh báo cáo quản trị tháng. Phỏng vấn mình từng câu: báo cáo gửi ai, gồm những khoản mục nào, chênh lệch so với kế hoạch bao nhiêu phần trăm thì phải giải thích, giọng văn ra sao. Xong viết hướng dẫn cho Project. Nhớ thêm quy tắc: không bịa số, số tự tính phải ghi phép tính.", "url": "cap-5.html#p-cap-5-9"}, {"id": "p-cap-5-10", "page": "cap-5", "pageTitle": "Trợ lý biết nhớ việc", "level": 5, "kind": "lesson", "code": "5j", "title": "Trợ lý trả lời khách", "tags": ["kinhdoanh"], "section": "Biến thể theo ngành", "text": "Mình muốn tạo trợ lý soạn câu trả lời cho khách hàng đúng giọng công ty mình. Mình sẽ tải lên chính sách đổi trả, bảo hành và 10 câu trả lời mẫu mà sếp khen. Phỏng vấn mình từng câu về giọng điệu, cách xưng hô, điều gì không bao giờ hứa với khách. Xong viết hướng dẫn cho Project.", "url": "cap-5.html#p-cap-5-10"}, {"id": "p-cap-5-11", "page": "cap-5", "pageTitle": "Trợ lý biết nhớ việc", "level": 5, "kind": "lesson", "code": "5k", "title": "Trợ lý báo cáo hiện trường", "tags": ["vanhanh"], "section": "Biến thể theo ngành", "text": "Mình muốn tạo trợ lý viết báo cáo ngày công trường từ ghi chú vội và ảnh chụp của mình. Mình sẽ tải lên mẫu báo cáo ngày và 2 báo cáo cũ. Phỏng vấn mình từng câu: báo cáo gửi ai, gồm mục nào, sự cố nào phải báo ngay. Xong viết hướng dẫn cho Project, nhớ đánh dấu [CẦN KIỂM TRA] với khối lượng tự suy ra.", "url": "cap-5.html#p-cap-5-11"}, {"id": "p-cap-6-1", "page": "cap-6", "pageTitle": "Tự tạo công cụ không cần code", "level": 6, "kind": "lesson", "code": "6a", "title": "Hỏi thẳng bạn ấy", "tags": ["chung", "vanhanh"], "section": "Làm thật: từng bước", "text": "Nhóm mình hay quên hạn công việc. Mình muốn một công cụ nhỏ theo dõi tiến độ, cảnh báo trước hạn 5 ngày, nhưng không biết mô tả thế nào. Hỏi mình vài câu rồi làm luôn nhé. Giao diện tiếng Việt, hiện đại.", "url": "cap-6.html#p-cap-6-1"}, {"id": "p-cap-6-2", "page": "cap-6", "pageTitle": "Tự tạo công cụ không cần code", "level": 6, "kind": "lesson", "code": "6b", "title": "Trả lời gộp và làm luôn", "tags": ["chung"], "section": "Làm thật: từng bước", "text": "Mình trả lời gộp nhé: nhóm 5 người. Mỗi việc có tên việc, người phụ trách, ngày bắt đầu, hạn chót, trạng thái (Chưa làm / Đang làm / Xong). Tô đỏ việc quá hạn, cam việc còn 5 ngày trở xuống, xanh việc đã xong. Cần lọc theo người phụ trách, thanh % tiến độ cả dự án, nút xuất CSV để mở bằng Excel. Có sẵn 8 việc mẫu. Làm luôn đi.", "url": "cap-6.html#p-cap-6-2"}, {"id": "p-cap-6-3", "page": "cap-6", "pageTitle": "Tự tạo công cụ không cần code", "level": 6, "kind": "lesson", "code": "6c", "title": "Nhờ bạn ấy chỉ cách thử", "tags": ["chung"], "section": "Làm thật: từng bước", "text": "Chỉ mình 5 thao tác để thử xem app chạy đúng chưa. Mỗi thao tác ghi rõ: bấm vào đâu, và nếu đúng thì mình phải thấy gì.", "url": "cap-6.html#p-cap-6-3"}, {"id": "p-cap-6-4", "page": "cap-6", "pageTitle": "Tự tạo công cụ không cần code", "level": 6, "kind": "lesson", "code": "6d", "title": "Thêm tính năng", "tags": ["chung"], "section": "Làm thật: từng bước", "text": "Thêm cột mức ưu tiên (Cao / Trung bình / Thấp). Việc ưu tiên cao và sắp đến hạn xếp lên đầu.", "url": "cap-6.html#p-cap-6-4"}, {"id": "p-cap-6-5", "page": "cap-6", "pageTitle": "Tự tạo công cụ không cần code", "level": 6, "kind": "lesson", "code": "6e", "title": "Báo lỗi như nói chuyện", "tags": ["chung"], "section": "Làm thật: từng bước", "text": "Cái nút [Xuất CSV] bấm không ăn, bạn sửa giúp. Mình bấm vào thì [không có gì xảy ra / hiện thông báo: dán nội dung lỗi vào đây].", "url": "cap-6.html#p-cap-6-5"}, {"id": "p-cap-6-6", "page": "cap-6", "pageTitle": "Tự tạo công cụ không cần code", "level": 6, "kind": "lesson", "code": "6f", "title": "Đổi giao diện", "tags": ["chung", "doisong"], "section": "Làm thật: từng bước", "text": "Đẹp hơn được không? Mình muốn kiểu [vui vẻ, nhiều màu, dành cho trẻ con / tối giản, tông xanh dương / chữ thật to cho người lớn tuổi].", "url": "cap-6.html#p-cap-6-6"}, {"id": "p-cap-6-7", "page": "cap-6", "pageTitle": "Tự tạo công cụ không cần code", "level": 6, "kind": "lesson", "code": "6g", "title": "Gộp thành một file HTML", "tags": ["chung"], "section": "Làm thật: từng bước", "text": "Gộp toàn bộ app thành một file HTML duy nhất, không cần cài đặt gì, mở được bằng trình duyệt trên máy tính và điện thoại. Hướng dẫn mình cách lưu file này về máy, từng bước, cho người không rành máy tính.", "url": "cap-6.html#p-cap-6-7"}, {"id": "p-cap-6-8", "page": "cap-6", "pageTitle": "Tự tạo công cụ không cần code", "level": 6, "kind": "lesson", "code": "6h", "title": "Thử thách táo bạo", "tags": ["chung", "doisong"], "section": "Làm thật: từng bước", "text": "Mình có một ý tưởng hơi \"điên\": [mô tả công cụ hoặc trò chơi bạn muốn, càng cụ thể càng tốt: dành cho ai, để làm gì, vui hay nghiêm túc]. Mình không biết code. Hỏi mình vài câu rồi làm luôn bản đầu tiên. Mình sẽ cùng bạn sửa dần.", "url": "cap-6.html#p-cap-6-8"}, {"id": "p-cap-6-9", "page": "cap-6", "pageTitle": "Tự tạo công cụ không cần code", "level": 6, "kind": "lesson", "code": "6i", "title": "Hỏi lại cách app tính", "tags": ["chung"], "section": "Dám hỏi lại", "text": "Giải thích cho mình bằng lời thường: app quyết định một việc là đỏ, cam hay xanh theo quy tắc nào? Việc có hạn đúng 5 ngày nữa thì màu gì? Hạn đúng hôm nay thì sao? Dữ liệu mình nhập được lưu ở đâu, tải lại trang có mất không, người khác có xem được không?", "url": "cap-6.html#p-cap-6-9"}, {"id": "p-cap-6-10", "page": "cap-6", "pageTitle": "Tự tạo công cụ không cần code", "level": 6, "kind": "lesson", "code": "6j", "title": "Checklist rà soát hợp đồng", "tags": ["luat"], "section": "Biến thể theo ngành", "text": "Mình làm pháp chế. Mình muốn một checklist rà soát hợp đồng mua bán dạng app: tick từng mục (thanh toán, giao nhận, chuyển rủi ro, bảo hành, phạt vi phạm, giải quyết tranh chấp…), mỗi mục có ô ghi chú và mức rủi ro, cuối cùng in ra một trang tóm tắt. Hỏi mình vài câu rồi làm luôn.", "url": "cap-6.html#p-cap-6-10"}, {"id": "p-cap-6-11", "page": "cap-6", "pageTitle": "Tự tạo công cụ không cần code", "level": 6, "kind": "lesson", "code": "6k", "title": "Bảng tính khấu hao", "tags": ["ketoan"], "section": "Biến thể theo ngành", "text": "Mình muốn một công cụ tính khấu hao tài sản cố định theo phương pháp đường thẳng: nhập nguyên giá, ngày bắt đầu, số năm sử dụng; ra bảng khấu hao từng tháng, từng năm, có biểu đồ giá trị còn lại, xuất được CSV. Hỏi mình vài câu trước khi làm, và ghi rõ công thức để mình kiểm tra.", "url": "cap-6.html#p-cap-6-11"}, {"id": "p-cap-6-12", "page": "cap-6", "pageTitle": "Tự tạo công cụ không cần code", "level": 6, "kind": "lesson", "code": "6l", "title": "Công cụ lập báo giá", "tags": ["kinhdoanh"], "section": "Biến thể theo ngành", "text": "Mình muốn một công cụ lập báo giá: chọn sản phẩm từ danh sách, nhập số lượng, tự tính chiết khấu theo bậc số lượng, thuế VAT (mình tự nhập tỷ lệ), tổng tiền bằng số và bằng chữ, in ra một trang báo giá có chỗ cho logo công ty. Hỏi mình vài câu rồi làm luôn, dùng dữ liệu sản phẩm mẫu trước.", "url": "cap-6.html#p-cap-6-12"}, {"id": "p-cap-6-13", "page": "cap-6", "pageTitle": "Tự tạo công cụ không cần code", "level": 6, "kind": "lesson", "code": "6m", "title": "Sổ theo dõi bảo trì", "tags": ["vanhanh"], "section": "Biến thể theo ngành", "text": "Mình quản lý vận hành toà nhà. Mình muốn một sổ theo dõi bảo trì dạng app: ghi sự cố theo hạng mục (thang máy, điện, nước, phòng cháy chữa cháy), ngày báo, ngày xử lý, người xử lý, chi phí; thống kê hạng mục hỏng nhiều nhất và thời gian xử lý trung bình; nhắc lịch bảo dưỡng định kỳ sắp tới. Hỏi mình vài câu rồi làm luôn.", "url": "cap-6.html#p-cap-6-13"}, {"id": "p-cap-7-1", "page": "cap-7", "pageTitle": "Giao cả đầu việc cho AI agent", "level": 7, "kind": "lesson", "code": "7a", "title": "Làm quen với thư mục", "tags": ["chung"], "section": "Làm thật: từng bước", "text": "Trong thư mục này có số liệu tháng 9 của 5 chi nhánh. Chưa làm gì cả, bạn chỉ đọc qua từng file rồi kể lại cho mình: mỗi file của chi nhánh nào, trình bày kiểu gì, đơn vị tính là gì, có điểm gì bất thường cần lưu ý.", "url": "cap-7.html#p-cap-7-1"}, {"id": "p-cap-7-2", "page": "cap-7", "pageTitle": "Giao cả đầu việc cho AI agent", "level": 7, "kind": "lesson", "code": "7b", "title": "Giao cả đầu việc", "tags": ["ketoan", "chung"], "section": "Làm thật: từng bước", "text": "Đây là số liệu tháng 9 của 5 chi nhánh, mỗi nơi gửi một kiểu (có nơi tính bằng triệu đồng, có nơi viết thành đoạn văn). Mình cần báo cáo quản trị tháng gửi Giám đốc, lưu vào thư mục con tên \"output\":\n1. Một file Excel tổng hợp theo chi nhánh: kế hoạch doanh thu, doanh thu, % kế hoạch, giá vốn, chi phí bán hàng, chi phí quản lý, lợi nhuận trước thuế, và dòng tổng toàn công ty. Tất cả quy về đồng.\n2. Một file Word tóm tắt cho Giám đốc: chi nhánh hụt kế hoạch, chi phí bất thường, công nợ quá hạn trên 60 ngày, những việc cần Giám đốc quyết định.\n3. Một email gửi Giám đốc soạn sẵn, lưu thành file văn bản. KHÔNG gửi.\nViệc này quan trọng, cứ làm kỹ, không cần vội.\nMỗi con số phải chỉ ra được nguồn (file nào, sheet nào, dòng nào). Chỗ nào không chắc thì hỏi mình, không tự đoán. Xong thì tự đối chiếu tổng với từng file gốc, báo mình đã kiểm gì, chưa kiểm được gì.\nBạn cần biết gì thì hỏi mình trước, rồi trình kế hoạch cho mình duyệt trước khi làm nhé.", "url": "cap-7.html#p-cap-7-2"}, {"id": "p-cap-7-3", "page": "cap-7", "pageTitle": "Giao cả đầu việc cho AI agent", "level": 7, "kind": "lesson", "code": "7c", "title": "Duyệt kế hoạch có điều kiện", "tags": ["chung"], "section": "Làm thật: từng bước", "text": "Kế hoạch ổn. Trước khi làm, bổ sung giúp mình: [file HCM có mấy sheet, bạn định dùng sheet nào và vì sao?]. Trong file Excel, thêm một sheet tên \"Nguon\" ghi nguồn của từng con số. Xong thì làm đi, gặp chỗ không chắc thì dừng lại hỏi mình.", "url": "cap-7.html#p-cap-7-3"}, {"id": "p-cap-7-4", "page": "cap-7", "pageTitle": "Giao cả đầu việc cho AI agent", "level": 7, "kind": "lesson", "code": "7d", "title": "Hỏi tiến độ", "tags": ["chung"], "section": "Làm thật: từng bước", "text": "Đang làm tới đâu rồi? Có file nào bạn đọc chưa được, hay con số nào bạn đang phân vân không?", "url": "cap-7.html#p-cap-7-4"}, {"id": "p-cap-7-5", "page": "cap-7", "pageTitle": "Giao cả đầu việc cho AI agent", "level": 7, "kind": "lesson", "code": "7e", "title": "Tóm tắt thành phẩm", "tags": ["chung"], "section": "Làm thật: từng bước", "text": "Tóm tắt cho mình: 3 file nằm ở đâu, mỗi file có gì, 5 con số quan trọng nhất, và những điểm bạn chưa chắc chắn. Đừng gửi email.", "url": "cap-7.html#p-cap-7-5"}, {"id": "p-cap-7-6", "page": "cap-7", "pageTitle": "Giao cả đầu việc cho AI agent", "level": 7, "kind": "lesson", "code": "7f", "title": "Giao việc kiểu từng file", "tags": ["chung", "ketoan"], "section": "Làm thật: từng bước", "text": "Mình cần làm báo cáo quản trị tháng 9 từ số liệu 5 chi nhánh, mỗi nơi gửi một kiểu. Mình sẽ gửi từng file một. Với mỗi file, bạn chỉ cần: đọc kỹ, lấy ra kế hoạch doanh thu, doanh thu, giá vốn, chi phí bán hàng, chi phí quản lý, lợi nhuận trước thuế, công nợ quá hạn và ghi chú đáng chú ý; quy hết về đồng; ghi rõ mỗi con số nằm ở đâu trong file. Chưa tổng hợp vội. Chỗ nào không chắc thì hỏi mình. Sẵn sàng thì nói \"Gửi file đầu tiên đi\".", "url": "cap-7.html#p-cap-7-6"}, {"id": "p-cap-7-7", "page": "cap-7", "pageTitle": "Giao cả đầu việc cho AI agent", "level": 7, "kind": "lesson", "code": "7g", "title": "Tổng hợp sau khi đủ 5 file", "tags": ["chung", "ketoan"], "section": "Làm thật: từng bước", "text": "Đủ 5 chi nhánh rồi. Giờ làm giúp mình: (1) bảng tổng hợp theo chi nhánh và dòng toàn công ty; (2) báo cáo 1 trang cho Giám đốc: chi nhánh hụt kế hoạch, chi phí bất thường, công nợ quá hạn trên 60 ngày, việc cần Giám đốc quyết định; (3) email soạn sẵn gửi Giám đốc. Nếu công cụ cho phép, tạo file Excel và Word để mình tải về.", "url": "cap-7.html#p-cap-7-7"}, {"id": "p-cap-7-8", "page": "cap-7", "pageTitle": "Giao cả đầu việc cho AI agent", "level": 7, "kind": "lesson", "code": "7h", "title": "Hỏi lại quy đổi đơn vị", "tags": ["ketoan"], "section": "Dám hỏi lại", "text": "Số liệu của chi nhánh Hải Phòng bạn quy đổi đơn vị thế nào? Chỉ cho mình dòng gốc trong file để mình đối chiếu.", "url": "cap-7.html#p-cap-7-8"}, {"id": "p-cap-7-9", "page": "cap-7", "pageTitle": "Giao cả đầu việc cho AI agent", "level": 7, "kind": "lesson", "code": "7i", "title": "Hỏi lại các chỗ dễ sai khác", "tags": ["ketoan"], "section": "Dám hỏi lại", "text": "Thêm 3 câu nữa: (1) File HCM có mấy sheet, bạn lấy số ở sheet nào, vì sao? (2) File Cần Thơ dùng mã tài khoản: bạn hiểu mỗi mã là gì, và lấy kế hoạch doanh thu ở đâu? (3) Chi phí bán hàng HCM đã gồm các dòng chi tiết bên dưới chưa, bạn có cộng thêm lần nữa không?", "url": "cap-7.html#p-cap-7-9"}, {"id": "p-cap-7-10", "page": "cap-7", "pageTitle": "Giao cả đầu việc cho AI agent", "level": 7, "kind": "lesson", "code": "7j", "title": "Bảng theo dõi hạn hồ sơ", "tags": ["luat"], "section": "Biến thể theo ngành", "text": "Thư mục này có [30] hồ sơ vụ việc (Word, PDF, email đã lưu). Đọc từng hồ sơ, lập file Excel theo dõi: mã vụ việc, khách hàng (chỉ ghi mã), loại việc, mốc thời hạn sắp tới, người phụ trách, việc cần làm tiếp. Tô đỏ hồ sơ còn dưới 7 ngày đến hạn. Mỗi thời hạn ghi rõ lấy từ trang nào của hồ sơ nào. Trình kế hoạch cho mình duyệt trước.", "url": "cap-7.html#p-cap-7-10"}, {"id": "p-cap-7-11", "page": "cap-7", "pageTitle": "Giao cả đầu việc cho AI agent", "level": 7, "kind": "lesson", "code": "7k", "title": "Đối chiếu sao kê với sổ sách", "tags": ["ketoan"], "section": "Biến thể theo ngành", "text": "Thư mục có sao kê ngân hàng tháng [tháng] và sổ chi tiết tiền gửi xuất từ phần mềm kế toán. Đối chiếu từng giao dịch: khớp, lệch số tiền, có ở sao kê mà không có ở sổ, và ngược lại. Lập file Excel kết quả và danh sách khoản cần giải trình. Không sửa file gốc. Hỏi mình trước nếu có quy ước ghi sổ bạn chưa rõ, rồi trình kế hoạch cho mình duyệt.", "url": "cap-7.html#p-cap-7-11"}, {"id": "p-cap-7-12", "page": "cap-7", "pageTitle": "Giao cả đầu việc cho AI agent", "level": 7, "kind": "lesson", "code": "7l", "title": "So sánh báo giá nhà cung cấp", "tags": ["kinhdoanh"], "section": "Biến thể theo ngành", "text": "Thư mục có báo giá của 5 nhà cung cấp, mỗi nơi một định dạng (PDF, Excel, ảnh chụp). Gộp thành một bảng so sánh: mã hàng, đơn giá, đã gồm VAT chưa, chiết khấu, thời gian giao, bảo hành, điều kiện thanh toán. Đánh dấu chỗ các báo giá không cùng điều kiện để so sánh. Viết thêm 1 trang đề xuất chọn nhà cung cấp nào, vì sao. Trình kế hoạch trước khi làm.", "url": "cap-7.html#p-cap-7-12"}, {"id": "p-cap-7-13", "page": "cap-7", "pageTitle": "Giao cả đầu việc cho AI agent", "level": 7, "kind": "lesson", "code": "7m", "title": "Báo cáo tuần từ nhiều công trường", "tags": ["vanhanh"], "section": "Biến thể theo ngành", "text": "Thư mục có báo cáo ngày trong tuần của [3] công trường, mỗi đội viết một kiểu. Tổng hợp thành báo cáo tuần: khối lượng hoàn thành so với kế hoạch, nhân lực, sự cố an toàn, vật tư thiếu, việc cần Ban chỉ huy quyết định. Lưu thành file Word và một bảng Excel. Ghi rõ nguồn từng con số. Hỏi mình trước, rồi trình kế hoạch cho mình duyệt.", "url": "cap-7.html#p-cap-7-13"}, {"id": "p-an-toan-1", "page": "an-toan", "pageTitle": "Dùng AI an toàn & tỉnh táo", "level": 0, "kind": "page", "code": "AT1", "title": "Nhờ tạo bảng thay thế mẫu (không dùng dữ liệu thật)", "tags": ["meta", "chung"], "section": "Ẩn danh hoá: che trước, dán sau", "text": "Mình sắp ẩn danh một [hợp đồng / bảng công nợ / email khách hàng] trước khi nhờ AI đọc. Mình sẽ không gửi dữ liệu thật cho bạn.\nBạn tạo giúp mình một bảng thay thế mẫu gồm 3 cột: Loại thông tin, Mã thay thế gợi ý, Lưu ý khi thay. Liệt kê đủ các loại thông tin dễ bị sót trong loại tài liệu này của ngành [pháp lý / kế toán / kinh doanh / vận hành].\nCuối bảng, gợi ý thêm 5 từ khoá mình nên tìm bằng Ctrl+F để rà lần cuối.", "url": "an-toan.html#p-an-toan-1"}, {"id": "p-an-toan-2", "page": "an-toan", "pageTitle": "Dùng AI an toàn & tỉnh táo", "level": 0, "kind": "page", "code": "AT2", "title": "Soạn tin nhắn hỏi về chính sách AI", "tags": ["chung"], "section": "Hỏi công ty trước khi dùng", "text": "Mình muốn hỏi [quản lý / bộ phận IT] xem công ty có cho dùng AI trong công việc không và được đưa loại dữ liệu nào vào. Mình muốn tin nhắn nghe như đang muốn làm đúng quy định, chứ không như đang xin làm việc riêng.\nViết giúp mình một [tin nhắn Zalo / email] ngắn, lịch sự, kèm 4–5 câu hỏi cụ thể. Giọng [thân thiện / trang trọng].", "url": "an-toan.html#p-an-toan-2"}, {"id": "p-an-toan-3", "page": "an-toan", "pageTitle": "Dùng AI an toàn & tỉnh táo", "level": 0, "kind": "page", "code": "AT3", "title": "Căn cứ đâu?", "tags": ["meta"], "section": "Bộ câu \"Dám hỏi lại\"", "text": "Với mỗi ý bạn vừa đưa ra, trích nguyên văn câu trong tài liệu kèm số Điều (hoặc số trang). Chỗ nào là bạn suy luận chứ không có trong tài liệu thì ghi rõ \"suy luận\".", "url": "an-toan.html#p-an-toan-3"}, {"id": "p-an-toan-4", "page": "an-toan", "pageTitle": "Dùng AI an toàn & tỉnh táo", "level": 0, "kind": "page", "code": "AT4", "title": "Điểm nào bạn không chắc?", "tags": ["meta"], "section": "Bộ câu \"Dám hỏi lại\"", "text": "Trong câu trả lời vừa rồi, điểm nào bạn không chắc chắn nhất? Xếp từ ít chắc đến chắc nhất, và nói mình nên kiểm tra từng điểm ở đâu.", "url": "an-toan.html#p-an-toan-4"}, {"id": "p-an-toan-5", "page": "an-toan", "pageTitle": "Dùng AI an toàn & tỉnh táo", "level": 0, "kind": "page", "code": "AT5", "title": "Dặn trước: không có thì nói không có", "tags": ["meta"], "section": "Bộ câu \"Dám hỏi lại\"", "text": "Trước khi bắt đầu: chỉ trả lời dựa trên tài liệu mình gửi. Nếu tài liệu không có thông tin, nói rõ \"tài liệu không đề cập\", đừng đoán. Nếu bạn dùng kiến thức bên ngoài, đánh dấu riêng để mình biết.", "url": "an-toan.html#p-an-toan-5"}, {"id": "p-an-toan-6", "page": "an-toan", "pageTitle": "Dùng AI an toàn & tỉnh táo", "level": 0, "kind": "page", "code": "AT6", "title": "Làm sao để mình kiểm tra bạn?", "tags": ["meta"], "section": "Bộ câu \"Dám hỏi lại\"", "text": "Làm sao để mình biết bạn không bịa trong câu trả lời này? Gợi ý cho mình 3 cách cụ thể để tự kiểm tra, cách nhanh nhất trước.", "url": "an-toan.html#p-an-toan-6"}, {"id": "p-an-toan-7", "page": "an-toan", "pageTitle": "Dùng AI an toàn & tỉnh táo", "level": 0, "kind": "page", "code": "AT7", "title": "Chỉ cách tính", "tags": ["meta", "ketoan"], "section": "Bộ câu \"Dám hỏi lại\"", "text": "Chỉ cho mình từng bước bạn tính ra con số [___]: lấy từ dòng nào, cộng trừ thế nào, có làm tròn hay bỏ dòng nào không. Chọn 3 dòng bất kỳ để mình đối chiếu với file gốc.", "url": "an-toan.html#p-an-toan-7"}, {"id": "p-an-toan-8", "page": "an-toan", "pageTitle": "Dùng AI an toàn & tỉnh táo", "level": 0, "kind": "page", "code": "AT8", "title": "Văn bản còn hiệu lực không?", "tags": ["meta", "luat"], "section": "Bộ câu \"Dám hỏi lại\"", "text": "Bạn vừa dẫn [tên văn bản / số điều]. Văn bản này hiện còn hiệu lực không, đã bị sửa đổi hay thay thế chưa? Kiến thức của bạn cập nhật đến khi nào? Nếu không chắc thì nói thẳng, và chỉ mình nên tra ở nguồn chính thức nào.", "url": "an-toan.html#p-an-toan-8"}, {"id": "p-an-toan-9", "page": "an-toan", "pageTitle": "Dùng AI an toàn & tỉnh táo", "level": 0, "kind": "page", "code": "AT9", "title": "Đóng vai người soát lỗi khó tính", "tags": ["meta"], "section": "Bộ câu \"Dám hỏi lại\"", "text": "Giờ bạn đóng vai một người soát lỗi khó tính, đọc lại câu trả lời của chính bạn. Tìm mọi chỗ có thể sai: con số, ngày tháng, tên riêng, trích dẫn, suy luận vội. Liệt kê ra, rồi sửa những chỗ bạn chắc là sai.", "url": "an-toan.html#p-an-toan-9"}, {"id": "p-anh-chup-1", "page": "anh-chup", "pageTitle": "Chụp ảnh là nhờ được: ảnh, ảnh chụp màn hình, giấy tờ", "level": 0, "kind": "topic", "code": "AC1", "title": "Gửi ảnh kèm đủ 3 điều", "tags": ["chung", "meta"], "section": "Cách nhờ", "text": "Mình gửi [số] ảnh [hoá đơn / bảng trắng / màn hình báo lỗi]. Mình cần [bảng chi phí để nộp kế toán]. Làm [kỹ, đây là số liệu quyết toán / nhanh, nháp là được]. Để mình kiểm: chép đúng những gì đọc được, chỗ nào mờ hay không chắc thì ghi [?] và liệt kê ở cuối, đừng đoán. Thiếu gì thì hỏi mình trước.", "url": "anh-chup.html#p-anh-chup-1"}, {"id": "p-anh-chup-2", "page": "anh-chup", "pageTitle": "Chụp ảnh là nhờ được: ảnh, ảnh chụp màn hình, giấy tờ", "level": 0, "kind": "topic", "code": "AC2", "title": "Hoá đơn thành bảng chi phí", "tags": ["ketoan", "chung"], "section": "Làm thật", "text": "Đây là ảnh [10] hoá đơn của [chuyến công tác tháng 9]. Lập bảng: Ngày, Nhà cung cấp, Nội dung, Số tiền (VND), và cột \"Cần kiểm tra lại\" cho dòng đọc không chắc. Cuối bảng có dòng tổng. Sau bảng, liệt kê riêng các số không chắc, ghi rõ ảnh số mấy.", "url": "anh-chup.html#p-anh-chup-2"}, {"id": "p-anh-chup-3", "page": "anh-chup", "pageTitle": "Chụp ảnh là nhờ được: ảnh, ảnh chụp màn hình, giấy tờ", "level": 0, "kind": "topic", "code": "AC3", "title": "Bảng trắng thành biên bản", "tags": ["chung"], "section": "Làm thật", "text": "Ảnh này là bảng trắng sau cuộc họp [kế hoạch quý 4], chữ viết tay hơi xấu. Chuyển thành: (1) biên bản ngắn: đã bàn gì, chốt gì; (2) bảng việc cần làm: việc, người phụ trách, hạn. Chỗ nào không đọc ra hoặc không chắc mũi tên nối ý nào, ghi [?] và hỏi mình.", "url": "anh-chup.html#p-anh-chup-3"}, {"id": "p-anh-chup-4", "page": "anh-chup", "pageTitle": "Chụp ảnh là nhờ được: ảnh, ảnh chụp màn hình, giấy tờ", "level": 0, "kind": "topic", "code": "AC4", "title": "Màn hình báo lỗi", "tags": ["chung"], "section": "Làm thật", "text": "Mình đang [nhập công thức trong Excel trên Windows] thì hiện lỗi như ảnh. Mình không rành kỹ thuật, chỉ mình từng bước, nói rõ bấm vào đâu. Xong mỗi bước mình báo lại rồi mới sang bước tiếp.", "url": "anh-chup.html#p-anh-chup-4"}, {"id": "p-anh-chup-5", "page": "anh-chup", "pageTitle": "Chụp ảnh là nhờ được: ảnh, ảnh chụp màn hình, giấy tờ", "level": 0, "kind": "topic", "code": "AC5", "title": "Giải thích từng ô trong tờ khai", "tags": ["chung", "doisong"], "section": "Làm thật", "text": "Đây là ảnh mẫu [tờ khai / đơn đăng ký] còn trống. Giải thích từng ô: ô đó hỏi gì, thường lấy thông tin từ giấy tờ nào, lỗi hay gặp. Mình sẽ tự điền. Chỗ nào phụ thuộc quy định hiện hành, nói rõ để mình kiểm tra với nơi tiếp nhận.", "url": "anh-chup.html#p-anh-chup-5"}, {"id": "p-anh-chup-6", "page": "anh-chup", "pageTitle": "Chụp ảnh là nhờ được: ảnh, ảnh chụp màn hình, giấy tờ", "level": 0, "kind": "topic", "code": "AC6", "title": "Đọc biểu đồ, gợi ý câu hỏi", "tags": ["chung"], "section": "Làm thật", "text": "Đây là biểu đồ [doanh thu theo quý] mình sắp nghe trình bày. Cho mình: (1) biểu đồ nói gì, trong 3 câu; (2) điểm bất thường hoặc dễ gây hiểu lầm, như trục không bắt đầu từ 0; (3) 3 câu hỏi nên đặt cho người trình bày. Số nào ước lượng từ hình, ghi rõ là ước lượng.", "url": "anh-chup.html#p-anh-chup-6"}, {"id": "p-anh-chup-7", "page": "anh-chup", "pageTitle": "Chụp ảnh là nhờ được: ảnh, ảnh chụp màn hình, giấy tờ", "level": 0, "kind": "topic", "code": "AC7", "title": "Liệt kê chỗ đọc không chắc", "tags": ["chung"], "section": "Dám hỏi lại", "text": "Trước khi mình dùng: (1) liệt kê mọi ô, mọi số bạn đọc không chắc, ghi ảnh số mấy, vị trí nào; (2) với từng hoá đơn, cộng các dòng hàng và so với tổng in trên tờ, chỗ nào lệch thì báo; (3) mình gửi [10] ảnh, bảng có đủ [10] dòng không?", "url": "anh-chup.html#p-anh-chup-7"}, {"id": "p-anh-chup-8", "page": "anh-chup", "pageTitle": "Chụp ảnh là nhờ được: ảnh, ảnh chụp màn hình, giấy tờ", "level": 0, "kind": "topic", "code": "AC8", "title": "Tóm tắt công văn giấy", "tags": ["luat"], "section": "Biến thể theo ngành", "text": "Đây là ảnh công văn [đã che tên công ty và người ký]. Tóm tắt: ai yêu cầu gì, căn cứ nào được viện dẫn, thời hạn trả lời. Trích nguyên văn câu chứa thời hạn để mình đối chiếu với bản giấy.", "url": "anh-chup.html#p-anh-chup-8"}, {"id": "p-anh-chup-9", "page": "anh-chup", "pageTitle": "Chụp ảnh là nhờ được: ảnh, ảnh chụp màn hình, giấy tờ", "level": 0, "kind": "topic", "code": "AC9", "title": "Biên bản đối chiếu thành bảng", "tags": ["ketoan"], "section": "Biến thể theo ngành", "text": "Đây là ảnh biên bản đối chiếu công nợ [đã che tên và mã số thuế]. Chuyển thành bảng: Số hoá đơn, Ngày, Số tiền, Đã thanh toán, Còn lại. Ô nào đọc không chắc thì ghi [?]. Cộng cột Còn lại và so với số tổng in trên biên bản.", "url": "anh-chup.html#p-anh-chup-9"}, {"id": "p-anh-chup-10", "page": "anh-chup", "pageTitle": "Chụp ảnh là nhờ được: ảnh, ảnh chụp màn hình, giấy tờ", "level": 0, "kind": "topic", "code": "AC10", "title": "Ảnh hàng lỗi thành phản hồi", "tags": ["kinhdoanh"], "section": "Biến thể theo ngành", "text": "Khách gửi ảnh [ghế xoay] bị [nứt chân], mình đã cắt phần có mặt người và địa chỉ. Mô tả lỗi nhìn thấy, gợi ý 3 câu cần hỏi thêm để xét bảo hành, soạn tin trả lời ngắn, ân cần. Chỗ nào ảnh không đủ để kết luận, nói rõ.", "url": "anh-chup.html#p-anh-chup-10"}, {"id": "p-anh-chup-11", "page": "anh-chup", "pageTitle": "Chụp ảnh là nhờ được: ảnh, ảnh chụp màn hình, giấy tờ", "level": 0, "kind": "topic", "code": "AC11", "title": "Ảnh hiện trường thành báo cáo", "tags": ["vanhanh"], "section": "Biến thể theo ngành", "text": "Đây là [3] ảnh [vết thấm trần tầng hầm]. Viết phần mô tả hiện trạng cho báo cáo sự cố: vị trí, điều nhìn thấy, mức độ ước lượng, đề xuất kiểm tra tiếp. Phần đoán nguyên nhân ghi rõ là suy đoán.", "url": "anh-chup.html#p-anh-chup-11"}, {"id": "p-bat-dau-1", "page": "bat-dau", "pageTitle": "Làm quen người bạn AI", "level": 0, "kind": "page", "code": "0a", "title": "Bạn cần biết gì từ mình?", "tags": ["meta"], "section": "Chiêu tối thượng: \"Hỏi thẳng bạn ấy\"", "text": "Mình muốn [việc bạn cần]. Bạn cần biết gì từ mình để làm tốt nhất? Hỏi mình từng câu một nhé.", "url": "bat-dau.html#p-bat-dau-1"}, {"id": "p-bat-dau-2", "page": "bat-dau", "pageTitle": "Làm quen người bạn AI", "level": 0, "kind": "page", "code": "0b", "title": "Gợi ý việc bạn giúp được", "tags": ["meta"], "section": "Chiêu tối thượng: \"Hỏi thẳng bạn ấy\"", "text": "Mình có [file / tình huống] này nhưng chưa biết nên nhờ bạn làm gì. Bạn gợi ý 5 việc bạn có thể giúp mình?", "url": "bat-dau.html#p-bat-dau-2"}, {"id": "p-bat-dau-3", "page": "bat-dau", "pageTitle": "Làm quen người bạn AI", "level": 0, "kind": "page", "code": "0c", "title": "Mình làm nghề này, bạn giúp được gì?", "tags": ["meta"], "section": "Chiêu tối thượng: \"Hỏi thẳng bạn ấy\"", "text": "Mình làm nghề [___], mỗi ngày mình hay làm [___]. Bạn giúp được mình những việc gì? Gợi ý 10 việc, xếp từ dễ đến khó.", "url": "bat-dau.html#p-bat-dau-3"}, {"id": "p-bat-dau-4", "page": "bat-dau", "pageTitle": "Làm quen người bạn AI", "level": 0, "kind": "page", "code": "0d", "title": "Chưa đúng ý mà không biết nói sao", "tags": ["meta"], "section": "Chiêu tối thượng: \"Hỏi thẳng bạn ấy\"", "text": "Kết quả này chưa đúng ý mình lắm, nhưng mình cũng không biết diễn tả sao. Bạn hỏi mình vài câu để hiểu rõ hơn nhé.", "url": "bat-dau.html#p-bat-dau-4"}, {"id": "p-cong-cu-1", "page": "cong-cu", "pageTitle": "Bản đồ công cụ AI", "level": 0, "kind": "page", "code": "CC1", "title": "Thử cùng một việc ở hai bạn", "tags": ["meta"], "section": "Chọn bạn như chọn bạn", "text": "Mình đang thử so sánh hai công cụ AI cho cùng một việc. Việc của mình là: [mô tả việc]. Bối cảnh: [mình là ai, làm ở đâu, kết quả dùng để làm gì].\nLàm giúp mình, rồi cuối câu trả lời tự chấm bài của bạn theo 3 tiêu chí: đúng ý, dễ dùng ngay, có chỗ nào cần mình kiểm tra lại.", "url": "cong-cu.html#p-cong-cu-1"}, {"id": "p-cong-cu-2", "page": "cong-cu", "pageTitle": "Bản đồ công cụ AI", "level": 0, "kind": "page", "code": "CC2", "title": "Hỏi thẳng: việc này nên dùng công cụ gì?", "tags": ["meta"], "section": "Chọn bạn như chọn bạn", "text": "Mình cần [mô tả việc], thường làm [mỗi ngày / mỗi tuần / mỗi tháng], đầu vào là [loại file hoặc thông tin]. Theo bạn mình nên dùng loại công cụ AI nào, tính năng nào (ví dụ Project, upload file, Deep Research, agent)? Giải thích ngắn vì sao.\nNếu bạn không chắc tính năng hay gói hiện tại của công cụ nào đó, nói rõ để mình tự kiểm tra trang chính thức.", "url": "cong-cu.html#p-cong-cu-2"}, {"id": "p-giao-viec-nhu-dong-nghiep-1", "page": "giao-viec-nhu-dong-nghiep", "pageTitle": "Giao việc như giao cho đồng nghiệp", "level": 0, "kind": "page", "code": "DN1", "title": "Mẫu giao việc như giao cho đồng nghiệp", "tags": ["meta"], "section": "Mẫu câu giao việc", "text": "Mình cần [việc gì], để [dùng vào đâu / gửi cho ai].\n[Những gì một đồng nghiệp mới cần biết: ai, chuyện gì, thế nào là tốt.]\nCứ [làm nhanh gọn thôi / làm thật kỹ, không cần vội].\nXong thì tự kiểm tra bằng cách [___], rồi báo mình đã kiểm gì, chưa kiểm được gì.\nThiếu gì thì hỏi mình trước nhé.", "url": "giao-viec-nhu-dong-nghiep.html#p-giao-viec-nhu-dong-nghiep-1"}, {"id": "p-giao-viec-nhu-dong-nghiep-2", "page": "giao-viec-nhu-dong-nghiep", "pageTitle": "Giao việc như giao cho đồng nghiệp", "level": 0, "kind": "page", "code": "DN2", "title": "Biến câu nhờ quen thuộc thành kiểu đồng nghiệp", "tags": ["meta"], "section": "Mẫu câu giao việc", "text": "Đây là câu mình hay nhờ AI: \"[dán câu của bạn]\". Viết lại giúp mình theo kiểu giao việc cho một đồng nghiệp giỏi: nói rõ mình muốn gì, bỏ bao nhiêu công sức, và kiểm tra thế nào. Giải thích ngắn vì sao bản mới tốt hơn.", "url": "giao-viec-nhu-dong-nghiep.html#p-giao-viec-nhu-dong-nghiep-2"}, {"id": "p-giao-viec-nhu-dong-nghiep-3", "page": "giao-viec-nhu-dong-nghiep", "pageTitle": "Giao việc như giao cho đồng nghiệp", "level": 0, "kind": "page", "code": "DN3", "title": "Rà soát hợp đồng như giao cho đồng nghiệp", "tags": ["luat"], "section": "Biến thể theo ngành", "text": "Mình cần rà soát hợp đồng này cho phía [bên mua / bên bán], để báo sếp trước khi ký vào [ngày]. Thế nào là tốt: chỉ ra điều khoản bất lợi, rủi ro lớn nhất, và đề xuất sửa. Cứ làm kỹ. Mỗi ý trích nguyên văn kèm số Điều; ý nào là suy luận thì ghi rõ. Thiếu gì thì hỏi mình trước.", "url": "giao-viec-nhu-dong-nghiep.html#p-giao-viec-nhu-dong-nghiep-3"}, {"id": "p-giao-viec-nhu-dong-nghiep-4", "page": "giao-viec-nhu-dong-nghiep", "pageTitle": "Giao việc như giao cho đồng nghiệp", "level": 0, "kind": "page", "code": "DN4", "title": "Thuyết minh biến động chi phí", "tags": ["ketoan"], "section": "Biến thể theo ngành", "text": "Mình cần đoạn thuyết minh biến động chi phí tháng [X] so với tháng trước, để đưa vào báo cáo gửi Kế toán trưởng. Số liệu ở bảng dưới. Làm vừa phải, ngắn gọn. Xong thì tự cộng lại các khoản, đối chiếu với dòng tổng, và báo mình chỗ nào chưa khớp.\n[dán bảng số liệu đã che tên]", "url": "giao-viec-nhu-dong-nghiep.html#p-giao-viec-nhu-dong-nghiep-4"}, {"id": "p-giao-viec-nhu-dong-nghiep-5", "page": "giao-viec-nhu-dong-nghiep", "pageTitle": "Giao việc như giao cho đồng nghiệp", "level": 0, "kind": "page", "code": "DN5", "title": "Thư chào hàng cho khách cũ", "tags": ["kinhdoanh"], "section": "Biến thể theo ngành", "text": "Mình cần thư chào hàng sản phẩm [tên] cho khách cũ [mô tả khách], mục tiêu là hẹn được một cuộc gọi 15 phút. Giọng thân thiện, dưới 120 chữ. Làm 2 phương án. Đánh dấu mọi con số, ưu đãi, cam kết trong thư để mình kiểm tra lại, mình chỉ được hứa [điều được phép].", "url": "giao-viec-nhu-dong-nghiep.html#p-giao-viec-nhu-dong-nghiep-5"}, {"id": "p-giao-viec-nhu-dong-nghiep-6", "page": "giao-viec-nhu-dong-nghiep", "pageTitle": "Giao việc như giao cho đồng nghiệp", "level": 0, "kind": "page", "code": "DN6", "title": "Xếp lại lịch thi công khi bị trễ", "tags": ["vanhanh"], "section": "Biến thể theo ngành", "text": "Mình cần xếp lại lịch thi công tuần tới vì [hạng mục] bị trễ 3 ngày, để gửi các tổ đội chiều nay. Ràng buộc: [danh sách]. Cứ làm kỹ, thử vài cách sắp xếp rồi chọn cách ít ảnh hưởng nhất. Xong thì tự soát lại xem có tổ nào bị xếp trùng ca hoặc thiếu vật tư không, báo mình đã kiểm gì.", "url": "giao-viec-nhu-dong-nghiep.html#p-giao-viec-nhu-dong-nghiep-6"}, {"id": "p-giong-noi-1", "page": "giong-noi", "pageTitle": "Nói thay vì gõ: trò chuyện bằng giọng nói với AI", "level": 0, "kind": "topic", "code": "GN1", "title": "Mở đầu cuộc nói chuyện bằng giọng", "tags": ["chung", "meta"], "section": "Cách nhờ", "text": "Mình muốn [nghĩ cho rõ chuyện ___]. Cuối buổi mình cần [3 ý chính và 1 bước tiếp theo]. Mình có [10 phút], bạn trả lời ngắn thôi. Trước khi kết thúc, nhắc lại các tên, con số mình đã nói và tóm tắt thành văn bản. Thiếu gì thì hỏi mình, từng câu một.", "url": "giong-noi.html#p-giong-noi-1"}, {"id": "p-giong-noi-2", "page": "giong-noi", "pageTitle": "Nói thay vì gõ: trò chuyện bằng giọng nói với AI", "level": 0, "kind": "topic", "code": "GN2", "title": "Nghĩ thành tiếng", "tags": ["chung", "doisong"], "section": "Làm thật", "text": "Mình đang rối chuyện [___]. Mình sẽ kể lan man, bạn nghe hết, đừng vội khuyên. Sau đó hỏi mình từng câu ngắn. Khi mình nói \"chốt đi\", tóm lại: điều mình thật sự lo, các lựa chọn, và một bước nhỏ làm được ngay hôm nay.", "url": "giong-noi.html#p-giong-noi-2"}, {"id": "p-giong-noi-3", "page": "giong-noi", "pageTitle": "Nói thay vì gõ: trò chuyện bằng giọng nói với AI", "level": 0, "kind": "topic", "code": "GN3", "title": "Đóng vai người khó nói chuyện", "tags": ["chung"], "section": "Làm thật", "text": "Mình sắp phải [xin sếp tăng lương / nhắc khách quen trả nợ quá hạn / báo khách là hàng về trễ]. Bạn đóng vai [sếp / khách hàng], tính cách [bận rộn, hay cắt ngang]. Đừng dễ dãi, phản ứng như người thật. Khi mình nói \"dừng\", ra khỏi vai và góp ý thẳng 3 chỗ nên nói khác, kèm câu thay thế.", "url": "giong-noi.html#p-giong-noi-3"}, {"id": "p-giong-noi-4", "page": "giong-noi", "pageTitle": "Nói thay vì gõ: trò chuyện bằng giọng nói với AI", "level": 0, "kind": "topic", "code": "GN4", "title": "Luyện tiếng Anh công việc", "tags": ["chung"], "section": "Làm thật", "text": "Mình muốn luyện tiếng Anh để [họp online với đối tác nước ngoài], trình độ [nói được câu đơn giản]. Bạn đóng vai [đối tác], nói chậm, mỗi lượt một câu hỏi. Mình sai thì đừng ngắt ngay. Cứ sau 5 lượt, dừng lại, nói bằng tiếng Việt 2 lỗi đáng sửa nhất và cách nói tự nhiên hơn.", "url": "giong-noi.html#p-giong-noi-4"}, {"id": "p-giong-noi-5", "page": "giong-noi", "pageTitle": "Nói thay vì gõ: trò chuyện bằng giọng nói với AI", "level": 0, "kind": "topic", "code": "GN5", "title": "Ý tưởng lộn xộn thành việc cần làm", "tags": ["chung"], "section": "Làm thật", "text": "Mình sẽ đọc một mạch, hơi lộn xộn, bạn nghe hết rồi mới làm. [đọc ý tưởng]. Xong, xếp lại thành 3 nhóm: việc cần làm (ai làm, hạn nào nếu mình có nói), ý tưởng để nghĩ thêm, câu cần hỏi người khác. Chỗ nào không rõ, ghi [CHƯA RÕ], đừng tự đoán.", "url": "giong-noi.html#p-giong-noi-5"}, {"id": "p-giong-noi-6", "page": "giong-noi", "pageTitle": "Nói thay vì gõ: trò chuyện bằng giọng nói với AI", "level": 0, "kind": "topic", "code": "GN6", "title": "Nghe mình tập phát biểu", "tags": ["chung"], "section": "Làm thật", "text": "Mình sắp phát biểu về [chủ đề] khoảng [3 phút] trước [ai nghe]. Mình nói thử một lượt, bạn đừng ngắt. Xong, góp ý thẳng: câu mở có giữ được người nghe không, chỗ nào khó hiểu khi chỉ nghe, câu kết có đọng lại gì không. Rồi sửa giúp mình 2 đoạn yếu nhất.", "url": "giong-noi.html#p-giong-noi-6"}, {"id": "p-giong-noi-7", "page": "giong-noi", "pageTitle": "Nói thay vì gõ: trò chuyện bằng giọng nói với AI", "level": 0, "kind": "topic", "code": "GN7", "title": "Nhắc lại cho mình kiểm", "tags": ["chung"], "section": "Dám hỏi lại", "text": "Nhắc lại mọi tên người, con số, ngày tháng mình vừa nói để mình kiểm. Trong lời khuyên của bạn, phần nào mình nên kiểm tra lại với tài liệu hoặc người có chuyên môn?", "url": "giong-noi.html#p-giong-noi-7"}, {"id": "p-giong-noi-8", "page": "giong-noi", "pageTitle": "Nói thay vì gõ: trò chuyện bằng giọng nói với AI", "level": 0, "kind": "topic", "code": "GN8", "title": "Tập buổi tư vấn khó", "tags": ["luat"], "section": "Biến thể theo ngành", "text": "Bạn đóng vai giám đốc doanh nghiệp nhỏ, nóng ruột về [rủi ro trong hợp đồng thuê kho], hỏi dồn mình. Khi mình nói \"dừng\", chỉ ra chỗ mình dùng thuật ngữ khó hiểu và chỗ mình lỡ hứa chắc quá.", "url": "giong-noi.html#p-giong-noi-8"}, {"id": "p-giong-noi-9", "page": "giong-noi", "pageTitle": "Nói thay vì gõ: trò chuyện bằng giọng nói với AI", "level": 0, "kind": "topic", "code": "GN9", "title": "Tập giải trình chênh lệch", "tags": ["ketoan"], "section": "Biến thể theo ngành", "text": "Mình sắp giải trình vì chi phí [tiếp khách] quý này vượt kế hoạch [20%]. Bạn đóng vai giám đốc kỹ tính, hỏi vặn từng con số. Sau 5 lượt, chỉ ra câu nào mình nói dài dòng, chỗ nào cần mang số liệu chứng minh.", "url": "giong-noi.html#p-giong-noi-9"}, {"id": "p-giong-noi-10", "page": "giong-noi", "pageTitle": "Nói thay vì gõ: trò chuyện bằng giọng nói với AI", "level": 0, "kind": "topic", "code": "GN10", "title": "Luyện gọi chào hàng", "tags": ["kinhdoanh"], "section": "Biến thể theo ngành", "text": "Bạn đóng vai trưởng phòng hành chính đang bận, nhận cuộc gọi chào hàng [thiết bị văn phòng] của mình. Từ chối mình 2 lần bằng 2 lý do khác nhau. Xong, gợi ý 2 câu mở đầu tốt hơn câu của mình.", "url": "giong-noi.html#p-giong-noi-10"}, {"id": "p-giong-noi-11", "page": "giong-noi", "pageTitle": "Nói thay vì gõ: trò chuyện bằng giọng nói với AI", "level": 0, "kind": "topic", "code": "GN11", "title": "Đi một vòng, ra báo cáo ngày", "tags": ["vanhanh"], "section": "Biến thể theo ngành", "text": "Mình vừa kiểm tra [kho / công trường], giờ đọc lại những gì thấy. Viết thành báo cáo ngày: hạng mục đạt, vấn đề phát hiện, việc cần xử lý (ai, hạn nào). Chỗ nào mình không nói, ghi [CẦN BỔ SUNG].", "url": "giong-noi.html#p-giong-noi-11"}, {"id": "p-giong-van-1", "page": "giong-van", "pageTitle": "Viết đúng giọng của bạn và của công ty", "level": 0, "kind": "topic", "code": "GV1", "title": "Viết đúng giọng mình theo 3 điều", "tags": ["chung", "meta"], "section": "Cách nhờ", "text": "Mình cần viết [loại văn bản] gửi [ai] để [mục đích], đúng giọng mình theo bản mô tả giọng văn và bảng thuật ngữ bên dưới.\nĐây là [bản nháp nhanh / bản gửi thật, làm kỹ].\nViết xong, tự soát theo bản mô tả và bảng thuật ngữ, rồi báo mình đã sửa những câu nào.\nThiếu thông tin gì thì hỏi mình trước nhé.\n\n[Bản mô tả giọng văn]\n[Bảng thuật ngữ]", "url": "giong-van.html#p-giong-van-1"}, {"id": "p-giong-van-2", "page": "giong-van", "pageTitle": "Viết đúng giọng của bạn và của công ty", "level": 0, "kind": "topic", "code": "GV2", "title": "Rút ra bản mô tả giọng văn", "tags": ["chung", "meta"], "section": "Làm thật", "text": "Dưới đây là [4] bài mình từng viết (đã che tên và số). Viết \"bản mô tả giọng văn\" dưới 250 chữ: độ dài câu, cách xưng hô, cách mở và kết, từ mình hay dùng, từ mình không bao giờ dùng, mức trang trọng. Mỗi điểm kèm một câu trích từ bài của mình. Điểm nào bạn đoán thì ghi rõ.\n\n[Dán các bài viết]", "url": "giong-van.html#p-giong-van-2"}, {"id": "p-giong-van-3", "page": "giong-van", "pageTitle": "Viết đúng giọng của bạn và của công ty", "level": 0, "kind": "topic", "code": "GV3", "title": "Gói gọn để dán vào cài đặt", "tags": ["meta"], "section": "Làm thật", "text": "Rút gọn bản mô tả ở trên thành các quy tắc ngắn dưới 150 chữ, mở đầu bằng \"Khi viết thay mình:\", để mình dán vào [hướng dẫn tuỳ chỉnh / Project]. Giữ 3 câu ví dụ tiêu biểu nhất.", "url": "giong-van.html#p-giong-van-3"}, {"id": "p-giong-van-4", "page": "giong-van", "pageTitle": "Viết đúng giọng của bạn và của công ty", "level": 0, "kind": "topic", "code": "GV4", "title": "Lập bảng thuật ngữ công ty", "tags": ["chung"], "section": "Làm thật", "text": "Lập giúp mình bảng thuật ngữ cho văn bản gửi khách, 3 cột: Dùng · Không dùng · Ghi chú. Quy ước sẵn có: gọi \"khách hàng\", không gọi \"quý khách\"; viết \"Sao Mai\", không viết \"SaoMai\"; [tên sản phẩm viết đúng]. Đọc [3 email mẫu] dưới đây, đề xuất thêm từ nên thống nhất, rồi hỏi mình duyệt từng dòng.", "url": "giong-van.html#p-giong-van-4"}, {"id": "p-giong-van-5", "page": "giong-van", "pageTitle": "Viết đúng giọng của bạn và của công ty", "level": 0, "kind": "topic", "code": "GV5", "title": "Một thông điệp cho 3 người đọc", "tags": ["chung"], "section": "Làm thật", "text": "Mình cần báo: [ví dụ: lô hàng giao khách chậm 5 ngày vì nhà cung cấp giao thiếu]. Viết 3 bản theo giọng của mình:\n1. Cho sếp: 3–4 dòng, ảnh hưởng, phương án, điều cần sếp quyết.\n2. Cho khách: xin lỗi chân thành, hẹn ngày mới rõ ràng, không đổ lỗi.\n3. Cho đồng nghiệp kho: tin nhắn ngắn, ai làm gì, trước khi nào.\nRồi chỉ ra 3 điểm khác nhau lớn nhất giữa ba bản.", "url": "giong-van.html#p-giong-van-5"}, {"id": "p-giong-van-6", "page": "giong-van", "pageTitle": "Viết đúng giọng của bạn và của công ty", "level": 0, "kind": "topic", "code": "GV6", "title": "Khử mùi AI", "tags": ["chung"], "section": "Làm thật", "text": "Đọc bản nháp dưới đây, chỉ ra mọi chỗ \"nghe như máy viết\": sáo ngữ, câu văn dịch, liệt kê vô hồn, mở và kết chung chung, kèm lý do. Rồi viết lại theo bản mô tả giọng văn của mình, không thêm ý, không bỏ thông tin.\n\n[Dán bản nháp]", "url": "giong-van.html#p-giong-van-6"}, {"id": "p-giong-van-7", "page": "giong-van", "pageTitle": "Viết đúng giọng của bạn và của công ty", "level": 0, "kind": "topic", "code": "GV7", "title": "Chấm bài theo giọng văn", "tags": ["chung"], "section": "Làm thật", "text": "Chấm bài dưới đây theo bản mô tả giọng văn và bảng thuật ngữ của mình, thang 10 điểm. Mỗi điểm trừ: trích câu, nói lệch quy tắc nào, đề xuất câu sửa. Đừng sửa chỗ đã đúng giọng chỉ vì bạn thích cách viết khác.\n\n[Dán bài viết]", "url": "giong-van.html#p-giong-van-7"}, {"id": "p-giong-van-8", "page": "giong-van", "pageTitle": "Viết đúng giọng của bạn và của công ty", "level": 0, "kind": "topic", "code": "GV8", "title": "Soi lỗi bắt chước quá đà", "tags": ["chung"], "section": "Dám hỏi lại", "text": "So bản vừa viết với các bài gốc của mình. Những cụm từ đặc trưng của mình xuất hiện bao nhiêu lần trong bài gốc, bao nhiêu lần trong bản mới? Chỗ nào dùng dày hơn hẳn thì viết lại cho tự nhiên.", "url": "giong-van.html#p-giong-van-8"}, {"id": "p-giong-van-9", "page": "giong-van", "pageTitle": "Viết đúng giọng của bạn và của công ty", "level": 0, "kind": "topic", "code": "GV9", "title": "Giọng thư tư vấn của hãng", "tags": ["luat"], "section": "Biến thể theo ngành", "text": "Đây là 3 thư tư vấn của hãng mình (đã che tên khách và vụ việc). Rút ra bản mô tả giọng văn: cách mở đầu, cách dẫn chiếu điều luật, mức độ khẳng định khi kết luận. Rồi viết lại đoạn nháp dưới đây theo giọng đó, giữ nguyên mọi dẫn chiếu.", "url": "giong-van.html#p-giong-van-9"}, {"id": "p-giong-van-10", "page": "giong-van", "pageTitle": "Viết đúng giọng của bạn và của công ty", "level": 0, "kind": "topic", "code": "GV10", "title": "Thống nhất tên khoản mục", "tags": ["ketoan"], "section": "Biến thể theo ngành", "text": "Từ 3 bản thuyết minh báo cáo quản trị cũ dưới đây, lập bảng: mỗi khoản mục đang được gọi bằng những tên nào, nên thống nhất tên nào. Rồi soát bản nháp tháng này, chỉ ra chỗ gọi tên lệch bảng.", "url": "giong-van.html#p-giong-van-10"}, {"id": "p-giong-van-11", "page": "giong-van", "pageTitle": "Viết đúng giọng của bạn và của công ty", "level": 0, "kind": "topic", "code": "GV11", "title": "Giọng CSKH của công ty", "tags": ["kinhdoanh"], "section": "Biến thể theo ngành", "text": "Đây là 5 câu trả lời khách mà sếp khen (đã che tên). Rút ra giọng chăm sóc khách hàng của công ty, rồi trả lời tình huống sau theo giọng đó, một bản email, một bản tin nhắn Zalo: [mô tả tình huống].", "url": "giong-van.html#p-giong-van-11"}, {"id": "p-giong-van-12", "page": "giong-van", "pageTitle": "Viết đúng giọng của bạn và của công ty", "level": 0, "kind": "topic", "code": "GV12", "title": "Thông báo đúng giọng công trường", "tags": ["vanhanh"], "section": "Biến thể theo ngành", "text": "Viết lại thông báo dưới đây cho anh em công trường đọc trên điện thoại: câu ngắn, ai làm gì, trước giờ nào. Giữ giọng như 2 thông báo cũ mình dán kèm. Phần an toàn giữ nguyên ý, không làm mềm.", "url": "giong-van.html#p-giong-van-12"}, {"id": "p-hoc-nhanh-1", "page": "hoc-nhanh", "pageTitle": "Học nhanh mọi thứ với một gia sư kiên nhẫn", "level": 0, "kind": "topic", "code": "HN1", "title": "Nhờ gia sư theo 3 điều", "tags": ["chung", "meta"], "section": "Cách nhờ", "text": "Mình muốn học [chủ đề] để [dùng vào việc gì]. Hiện mình [đã biết gì, chưa biết gì].\nMình có [15 phút mỗi tối trong 2 tuần], muốn học chắc phần cốt lõi.\nMỗi lần giải thích một ý ngắn, rồi hỏi mình một câu để kiểm tra. Mình sai thì gợi ý, đừng đưa đáp án ngay.\nCần biết thêm gì về mình thì hỏi trước nhé.", "url": "hoc-nhanh.html#p-hoc-nhanh-1"}, {"id": "p-hoc-nhanh-2", "page": "hoc-nhanh", "pageTitle": "Học nhanh mọi thứ với một gia sư kiên nhẫn", "level": 0, "kind": "topic", "code": "HN2", "title": "Giải thích theo 3 mức", "tags": ["chung"], "section": "Làm thật", "text": "Giải thích giúp mình [chủ đề, ví dụ: báo cáo lưu chuyển tiền tệ] theo 3 mức:\n1. Cho người mới: khoảng 5 câu, một ví dụ đời thường, không thuật ngữ.\n2. Cho người đã biết chút ít: các khái niệm chính liên quan với nhau thế nào.\n3. Cho chuyên gia: điểm tinh tế, chỗ người ta hay hiểu sai.\nXong thì hỏi mình muốn đào sâu phần nào.", "url": "hoc-nhanh.html#p-hoc-nhanh-2"}, {"id": "p-hoc-nhanh-3", "page": "hoc-nhanh", "pageTitle": "Học nhanh mọi thứ với một gia sư kiên nhẫn", "level": 0, "kind": "topic", "code": "HN3", "title": "Hỏi mình, đừng đưa đáp án", "tags": ["chung"], "section": "Làm thật", "text": "Mình muốn hiểu [câu hỏi, ví dụ: vì sao công ty có lãi mà vẫn thiếu tiền]. Dẫn dắt mình bằng câu hỏi, mỗi lần một câu, để mình tự suy ra. Mình sai hoặc bí thì gợi ý thêm chút ít; chỉ khi mình nói \"chịu\" mới giải thích. Cuối buổi, tóm tắt 3 điều mình đã tự tìm ra.", "url": "hoc-nhanh.html#p-hoc-nhanh-3"}, {"id": "p-hoc-nhanh-4", "page": "hoc-nhanh", "pageTitle": "Học nhanh mọi thứ với một gia sư kiên nhẫn", "level": 0, "kind": "topic", "code": "HN4", "title": "Kèm con học, không làm hộ", "tags": ["doisong"], "section": "Làm thật", "text": "Con mình học lớp [___], đang bí bài này: [chép đề hoặc gửi ảnh]. Đừng giải hộ. Gợi ý từng bước nhỏ để con tự làm. Con nghĩ đúng hướng thì khen cách nghĩ, không chỉ khen đáp án. Nói bằng lời hợp với tuổi con.", "url": "hoc-nhanh.html#p-hoc-nhanh-4"}, {"id": "p-hoc-nhanh-5", "page": "hoc-nhanh", "pageTitle": "Học nhanh mọi thứ với một gia sư kiên nhẫn", "level": 0, "kind": "topic", "code": "HN5", "title": "Ra đề và chấm điểm", "tags": ["chung"], "section": "Làm thật", "text": "Mình vừa học xong [chủ đề]. Ra 5 câu từ dễ đến khó, ít nhất 2 câu là tình huống thật trong nghề [nghề của mình]. Đưa từng câu, chờ mình trả lời rồi chấm: đúng, đúng một phần hay sai, vì sao. Cuối cùng nói mình cần ôn phần nào.", "url": "hoc-nhanh.html#p-hoc-nhanh-5"}, {"id": "p-hoc-nhanh-6", "page": "hoc-nhanh", "pageTitle": "Học nhanh mọi thứ với một gia sư kiên nhẫn", "level": 0, "kind": "topic", "code": "HN6", "title": "Lộ trình 2 tuần", "tags": ["chung"], "section": "Làm thật", "text": "Sau 2 tuần, mình muốn [kỹ năng, ví dụ: dùng thành thạo SUMIFS và PivotTable / hiểu một quy định mới của ngành]. Mỗi ngày mình có [20] phút. Hỏi trình độ của mình trước, rồi lập lộ trình 14 ngày: mỗi ngày học gì, làm bài tập nhỏ gì. Ngày 14 là bài \"thi cuối kỳ\" sát với việc thật: [mô tả việc].", "url": "hoc-nhanh.html#p-hoc-nhanh-6"}, {"id": "p-hoc-nhanh-7", "page": "hoc-nhanh", "pageTitle": "Học nhanh mọi thứ với một gia sư kiên nhẫn", "level": 0, "kind": "topic", "code": "HN7", "title": "Đọc xong, hỏi mình", "tags": ["chung"], "section": "Làm thật", "text": "Mình vừa tải lên [tên tài liệu], cần hiểu đủ để [áp dụng vào việc gì]. Cho mình dàn ý 5–7 ý chính trước. Đọc xong phần nào mình sẽ báo, bạn hỏi mình 3 câu về phần đó. Khi chấm, trích đúng điều, mục hoặc trang để mình đối chiếu.", "url": "hoc-nhanh.html#p-hoc-nhanh-7"}, {"id": "p-hoc-nhanh-8", "page": "hoc-nhanh", "pageTitle": "Học nhanh mọi thứ với một gia sư kiên nhẫn", "level": 0, "kind": "topic", "code": "HN8", "title": "Chỉ nguồn để mình đối chiếu", "tags": ["chung"], "section": "Dám hỏi lại", "text": "Trong phần bạn vừa giải thích, ý nào là kiến thức nền ít thay đổi, ý nào có thể đã thay đổi theo thời gian? Với nhóm sau, chỉ mình nguồn chính thức để đối chiếu và nói bạn chắc đến đâu. Không chắc thì nói thẳng.", "url": "hoc-nhanh.html#p-hoc-nhanh-8"}, {"id": "p-hoc-nhanh-9", "page": "hoc-nhanh", "pageTitle": "Học nhanh mọi thứ với một gia sư kiên nhẫn", "level": 0, "kind": "topic", "code": "HN9", "title": "Văn bản mới khác gì văn bản cũ", "tags": ["luat"], "section": "Biến thể theo ngành", "text": "Mình tải lên [văn bản mới] và [văn bản cũ]. Chỉ dựa vào hai văn bản này, liệt kê điểm thay đổi ảnh hưởng tới [loại hợp đồng của mình], trích số điều. Rồi cho mình 3 tình huống thử áp dụng và nhận xét câu trả lời của mình.", "url": "hoc-nhanh.html#p-hoc-nhanh-9"}, {"id": "p-hoc-nhanh-10", "page": "hoc-nhanh", "pageTitle": "Học nhanh mọi thứ với một gia sư kiên nhẫn", "level": 0, "kind": "topic", "code": "HN10", "title": "Đọc báo cáo tài chính từng bước", "tags": ["ketoan"], "section": "Biến thể theo ngành", "text": "Mình tải lên báo cáo tài chính của [khách hàng] (đã che tên) để xem họ có trả nợ nổi không. Dạy mình từng bước trên chính báo cáo này: xem chỉ tiêu nào, tính chỉ số nào, dấu hiệu nào đáng lo. Mỗi bước hỏi mình một câu.", "url": "hoc-nhanh.html#p-hoc-nhanh-10"}, {"id": "p-hoc-nhanh-11", "page": "hoc-nhanh", "pageTitle": "Học nhanh mọi thứ với một gia sư kiên nhẫn", "level": 0, "kind": "topic", "code": "HN11", "title": "Hiểu ngành của khách trong 30 phút", "tags": ["kinhdoanh"], "section": "Biến thể theo ngành", "text": "Tuần sau mình gặp khách ngành [ngành] mà mình chưa biết gì. Giúp mình nắm: họ kiếm tiền thế nào, lo nhất điều gì, hay dùng từ chuyên môn nào. Rồi đóng vai khách hỏi mình 5 câu và chấm điểm.", "url": "hoc-nhanh.html#p-hoc-nhanh-11"}, {"id": "p-hoc-nhanh-12", "page": "hoc-nhanh", "pageTitle": "Học nhanh mọi thứ với một gia sư kiên nhẫn", "level": 0, "kind": "topic", "code": "HN12", "title": "Quy trình thành câu hỏi kiểm tra", "tags": ["vanhanh"], "section": "Biến thể theo ngành", "text": "Mình tải lên [quy trình vận hành thiết bị]. Giải thích theo 3 mức, rồi soạn 10 câu hỏi nhanh kèm đáp án để kiểm tra anh em trước ca. Đánh dấu chỗ liên quan an toàn để mình đối chiếu văn bản gốc và hỏi cán bộ kỹ thuật.", "url": "hoc-nhanh.html#p-hoc-nhanh-12"}, {"id": "p-hoi-dap-1", "page": "hoi-dap", "pageTitle": "Hỏi đáp thường gặp", "level": 0, "kind": "page", "code": "HD1", "title": "Bạn giúp được mình việc gì?", "tags": ["chung"], "section": "Bắt đầu", "text": "Mình làm [nghề / vị trí] ở [loại công ty]. Mỗi ngày mình hay làm [kể 3–5 việc]. Bạn giúp được mình những việc gì? Gợi ý 10 việc, xếp từ dễ đến khó, mỗi việc kèm một câu mở lời để mình thử ngay.", "url": "hoi-dap.html#p-hoi-dap-1"}, {"id": "p-hoi-dap-2", "page": "hoi-dap", "pageTitle": "Hỏi đáp thường gặp", "level": 0, "kind": "page", "code": "HD2", "title": "Hỏi thẳng về chuyện học AI", "tags": ["meta"], "section": "Câu hỏi của bạn chưa có ở đây?", "text": "Mình là [nghề], đang tự học dùng AI cho công việc, hiện đã biết [kể những gì đã biết]. Mình đang vướng chỗ này: [câu hỏi]. Bạn trả lời ngắn gọn, thực tế, rồi gợi ý 1 việc nhỏ mình làm thử được ngay hôm nay.", "url": "hoi-dap.html#p-hoi-dap-2"}, {"id": "p-hop-hanh-1", "page": "hop-hanh", "pageTitle": "Họp nhẹ hơn: từ chuẩn bị đến biên bản và việc cần làm", "level": 0, "kind": "topic", "code": "HH1", "title": "Biên bản họp: câu mẫu", "tags": ["chung"], "section": "Cách nhờ", "text": "Đây là ghi chú vội cuộc họp [tên], ngày [___], thành phần [___]. Viết biên bản gửi [cả nhóm / sếp], gọn 1 trang: điều đã thống nhất, việc cần làm (ai, việc gì, hạn), vấn đề còn treo. Làm nhanh, không cần văn hoa.\nCách kiểm: chỉ ghi điều có trong ghi chú; chưa chốt thì để ở \"vấn đề còn treo\"; không rõ ai làm, hạn nào thì ghi [CẦN XÁC NHẬN], đừng tự điền.\nThiếu gì thì hỏi mình trước nhé.\n[dán ghi chú]", "url": "hop-hanh.html#p-hop-hanh-1"}, {"id": "p-hop-hanh-2", "page": "hop-hanh", "pageTitle": "Họp nhẹ hơn: từ chuẩn bị đến biên bản và việc cần làm", "level": 0, "kind": "topic", "code": "HH2", "title": "Chương trình họp và tập phản biện", "tags": ["chung", "ketoan"], "section": "Làm thật", "text": "Thứ Tư tới phòng mình họp 60 phút về triển khai phần mềm kế toán mới, 5 người từ tài chính, kế toán, IT, kho. Mục tiêu: chốt ngày chạy chính thức, kế hoạch chuyển dữ liệu, lịch đào tạo. Soạn chương trình họp và nửa trang đọc trước cho từng người. Xong, đóng vai Kế toán trưởng rất cẩn trọng, hỏi mình 3 câu khó nhất, từng câu một.", "url": "hop-hanh.html#p-hop-hanh-2"}, {"id": "p-hop-hanh-3", "page": "hop-hanh", "pageTitle": "Họp nhẹ hơn: từ chuẩn bị đến biên bản và việc cần làm", "level": 0, "kind": "topic", "code": "HH3", "title": "Ghi chú vội thành biên bản", "tags": ["chung", "ketoan"], "section": "Làm thật", "text": "Viết ghi chú vội này thành biên bản gửi cả nhóm. Chỉ ghi điều có trong ghi chú; ý chưa chốt để ở \"vấn đề còn treo\"; chỗ không rõ ghi [CẦN XÁC NHẬN].\n\nhop trien khai PM ke toan moi, 14/10, a Minh chu tri\ntp: a Minh GDTC, c Lan KTT, a Tuan IT, c Ngoc cong no, a Phong kho\n- go-live 1/1/2027?? a Minh muon chot, c Lan xin them 1 tuan\n- chuyen DL: so du dau ky, DM KH, hang hoa. c Ngoc: cong no le nhieu, doi chieu xong truoc 15/12\n- a Tuan: may cu yeu, co the mua them 2 may, chua co bao gia\n- dao tao 2 buoi, NCC day, ngay chua chot\n- a Phong hoi ma hang cu/moi ai map?? chua ai nhan\n- c Lan de xuat chay song song 1 thang. a Minh: xem chi phi da\n- hop lai tuan sau", "url": "hop-hanh.html#p-hop-hanh-3"}, {"id": "p-hop-hanh-4", "page": "hop-hanh", "pageTitle": "Họp nhẹ hơn: từ chuẩn bị đến biên bản và việc cần làm", "level": 0, "kind": "topic", "code": "HH4", "title": "Bảng việc và email sau họp", "tags": ["chung"], "section": "Làm thật", "text": "Từ biên bản này, lập bảng việc cần làm: Việc, Người phụ trách, Hạn. Chưa có người hay hạn thì để trống và đánh dấu, đừng tự gán. Rồi soạn email gửi cả nhóm: 3 điểm chính, bảng việc, và mời mọi người phản hồi trước [hạn] nếu ghi nhận chưa đúng.", "url": "hop-hanh.html#p-hop-hanh-4"}, {"id": "p-hop-hanh-5", "page": "hop-hanh", "pageTitle": "Họp nhẹ hơn: từ chuẩn bị đến biên bản và việc cần làm", "level": 0, "kind": "topic", "code": "HH5", "title": "Tóm tắt khi mình vắng mặt", "tags": ["chung"], "section": "Làm thật", "text": "Mình vắng [cuộc họp / chuỗi email] này, mình là [vai trò]. Đọc nội dung bên dưới (đã che tên): tóm tắt 5 dòng; điều gì đã chốt, ai chốt; việc nào giao cho mình; quyết định nào đang chờ mình, kèm 2–3 phương án. Chỗ các bên nói khác nhau thì chỉ ra, trích câu gốc ngắn.\n[dán nội dung]", "url": "hop-hanh.html#p-hop-hanh-5"}, {"id": "p-hop-hanh-6", "page": "hop-hanh", "pageTitle": "Họp nhẹ hơn: từ chuẩn bị đến biên bản và việc cần làm", "level": 0, "kind": "topic", "code": "HH6", "title": "Soát biên bản với ghi chú gốc", "tags": ["meta", "chung"], "section": "Dám hỏi lại", "text": "Soát biên bản với ghi chú gốc: mỗi câu về người nhận việc, hạn, con số, quyết định là \"có trong ghi chú\", \"suy luận\" hay \"không có căn cứ\"? Sửa để chỉ giữ điều có căn cứ.", "url": "hop-hanh.html#p-hop-hanh-6"}, {"id": "p-hop-hanh-7", "page": "hop-hanh", "pageTitle": "Họp nhẹ hơn: từ chuẩn bị đến biên bản và việc cần làm", "level": 0, "kind": "topic", "code": "HH7", "title": "Biên bản làm việc với đối tác", "tags": ["luat"], "section": "Biến thể theo ngành", "text": "Từ ghi chú buổi làm việc với [đối tác] về [vụ việc] (đã che tên), soạn biên bản: ý kiến từng bên, điểm đã thống nhất, điểm còn bảo lưu. Giữ đúng ý, không diễn giải. Không rõ ai nói thì ghi [CẦN XÁC NHẬN].", "url": "hop-hanh.html#p-hop-hanh-7"}, {"id": "p-hop-hanh-8", "page": "hop-hanh", "pageTitle": "Họp nhẹ hơn: từ chuẩn bị đến biên bản và việc cần làm", "level": 0, "kind": "topic", "code": "HH8", "title": "Việc sau họp khoá sổ", "tags": ["ketoan"], "section": "Biến thể theo ngành", "text": "Lập bảng việc từ ghi chú họp khoá sổ tháng [tháng]: việc, người phụ trách, hạn, phải chờ việc nào trước. Sắp theo thứ tự làm. Chưa có người hoặc hạn thì ghi [CẦN XÁC NHẬN].", "url": "hop-hanh.html#p-hop-hanh-8"}, {"id": "p-hop-hanh-9", "page": "hop-hanh", "pageTitle": "Họp nhẹ hơn: từ chuẩn bị đến biên bản và việc cần làm", "level": 0, "kind": "topic", "code": "HH9", "title": "Email sau buổi gặp khách", "tags": ["kinhdoanh"], "section": "Biến thể theo ngành", "text": "Từ ghi chú buổi gặp khách hôm nay (đã che tên), soạn email cảm ơn kèm tóm tắt: nhu cầu khách nêu, điều đã thống nhất, bước tiếp theo của mỗi bên kèm hạn. Giọng thân thiện. Không hứa thêm điều gì ngoài ghi chú.", "url": "hop-hanh.html#p-hop-hanh-9"}, {"id": "p-hop-hanh-10", "page": "hop-hanh", "pageTitle": "Họp nhẹ hơn: từ chuẩn bị đến biên bản và việc cần làm", "level": 0, "kind": "topic", "code": "HH10", "title": "Biên bản giao ban công trường", "tags": ["vanhanh"], "section": "Biến thể theo ngành", "text": "Từ ghi chú giao ban công trường [tên dự án] sáng nay, soạn biên bản theo hạng mục: tiến độ so với kế hoạch, vướng mắc, việc cần làm (ai, hạn), lưu ý an toàn. Chỗ không rõ thì ghi [CẦN XÁC NHẬN].", "url": "hop-hanh.html#p-hop-hanh-10"}, {"id": "p-khoang-cach-1", "page": "khoang-cach", "pageTitle": "Khoảng cách AI: phễu 6 tỷ người và vị trí của bạn", "level": 0, "kind": "page", "code": "KC1", "title": "Mình đang ở tầng nào của phễu?", "tags": ["meta"], "section": "Bạn đang ở đâu?", "text": "Mình làm [nghề], dùng AI kiểu: [mô tả ngắn, ví dụ: vài lần một tuần, hỏi đáp, viết email]. Theo phễu của Karpathy (6 tỷ người gần như chưa dùng, 1–2 tỷ dùng thỉnh thoảng bản miễn phí, khoảng 20 triệu dùng bản mạnh nhất cho việc chuyên môn), bạn đoán mình đang ở đâu? Gợi ý 3 việc cụ thể trong công việc của mình để đi xuống một bậc trong 30 ngày tới. Cần biết thêm gì thì hỏi mình trước.", "url": "khoang-cach.html#p-khoang-cach-1"}, {"id": "p-khoang-cach-2", "page": "khoang-cach", "pageTitle": "Khoảng cách AI: phễu 6 tỷ người và vị trí của bạn", "level": 0, "kind": "page", "code": "KC2", "title": "Kế hoạch 30 ngày của riêng mình", "tags": ["meta"], "section": "Kế hoạch 30 ngày đi xuống một bậc", "text": "Mình muốn trong 30 ngày tới dùng AI sâu hơn trong công việc [nghề, vị trí]. Mỗi tuần mình có khoảng [số] phút. Lên giúp mình kế hoạch 4 tuần, mỗi tuần một việc thật trong công việc của mình, việc sau lớn hơn việc trước, tuần cuối là giao một việc nhiều bước. Mỗi tuần ghi rõ: việc gì, câu nhờ mẫu, và cách mình kiểm tra kết quả. Hỏi mình vài câu trước nếu cần.", "url": "khoang-cach.html#p-khoang-cach-2"}, {"id": "p-khoang-cach-3", "page": "khoang-cach", "pageTitle": "Khoảng cách AI: phễu 6 tỷ người và vị trí của bạn", "level": 0, "kind": "page", "code": "KC3", "title": "Dạy lại cho người thân", "tags": ["doisong"], "section": "Đừng chỉ bứt lên: kéo người khác theo", "text": "Mình muốn chỉ cho [bố mẹ / con / đồng nghiệp] cách dùng AI lần đầu. Họ [mô tả: tuổi, nghề, hay lo điều gì]. Gợi ý cho mình 3 việc đầu tiên thật hợp với họ, câu nói mở đầu để họ không ngại, và một điều an toàn họ cần nhớ.", "url": "khoang-cach.html#p-khoang-cach-3"}, {"id": "p-mot-ngay-1", "page": "mot-ngay", "pageTitle": "Một ngày làm việc cùng AI: bốn nghề, từ sáng đến tối", "level": 0, "kind": "topic", "code": "ND1", "title": "Văn bản mới có đụng tới mình không?", "tags": ["luat"], "section": "⚖️ Một ngày của người làm pháp lý", "text": "Mình làm pháp chế cho một công ty [phân phối thiết bị văn phòng]. Đây là văn bản mới lấy từ nguồn chính thức. Tóm giúp mình trong 5 dòng: quy định gì, hiệu lực khi nào, công ty mình phải làm gì khác. Văn bản không nói rõ thì ghi \"không đề cập\", đừng đoán.\n\n[Dán văn bản]", "url": "mot-ngay.html#p-mot-ngay-1"}, {"id": "p-mot-ngay-2", "page": "mot-ngay", "pageTitle": "Một ngày làm việc cùng AI: bốn nghề, từ sáng đến tối", "level": 0, "kind": "topic", "code": "ND2", "title": "Rà phụ lục, nói rõ 3 điều", "tags": ["luat"], "section": "⚖️ Một ngày của người làm pháp lý", "text": "Mình đính kèm hợp đồng gốc và phụ lục gia hạn (đã che tên, số tiền). Công ty mình là bên mua.\nMình muốn: các điểm bất lợi cho bên mua, xếp theo rủi ro, mỗi điểm kèm một câu đề nghị sửa để nói trong cuộc họp.\nCông sức: làm kỹ, gọn trong một trang.\nKiểm tra: trích nguyên văn, ghi số điều, đối chiếu với hợp đồng gốc. Báo mình đã kiểm gì, chưa kiểm được gì.", "url": "mot-ngay.html#p-mot-ngay-2"}, {"id": "p-mot-ngay-3", "page": "mot-ngay", "pageTitle": "Một ngày làm việc cùng AI: bốn nghề, từ sáng đến tối", "level": 0, "kind": "topic", "code": "ND3", "title": "Căn cứ đâu?", "tags": ["luat", "chung"], "section": "⚖️ Một ngày của người làm pháp lý", "text": "Bạn nói điều khoản [___] \"trái quy định\". Văn bản nào, điều mấy? Phần nào bạn chắc chắn, phần nào là suy luận? Không chắc thì nói thẳng, mình sẽ tự tra nguồn chính thức.", "url": "mot-ngay.html#p-mot-ngay-3"}, {"id": "p-mot-ngay-4", "page": "mot-ngay", "pageTitle": "Một ngày làm việc cùng AI: bốn nghề, từ sáng đến tối", "level": 0, "kind": "topic", "code": "ND4", "title": "Giải thích cho người không chuyên", "tags": ["luat"], "section": "⚖️ Một ngày của người làm pháp lý", "text": "Đồng nghiệp kinh doanh hỏi mình: khách muốn thêm điều khoản \"[dán điều khoản]\", có nên đồng ý không. Viết giúp mình tin nhắn dưới 120 chữ, lời thường: rủi ro chính, đề nghị sửa thế nào, và một câu đồng nghiệp nói thẳng được với khách.", "url": "mot-ngay.html#p-mot-ngay-4"}, {"id": "p-mot-ngay-5", "page": "mot-ngay", "pageTitle": "Một ngày làm việc cùng AI: bốn nghề, từ sáng đến tối", "level": 0, "kind": "topic", "code": "ND5", "title": "Công thức tính quá hạn", "tags": ["ketoan"], "section": "💰 Một ngày của người làm kế toán – tài chính", "text": "Bảng công nợ của mình: cột A mã khách hàng, B ngày hoá đơn, C số tiền, D ngày đã trả (trống nếu chưa trả). Hạn 30 ngày. Viết công thức cho cột E \"Số ngày quá hạn\" và F \"Tình trạng\" (Đã trả, Trong hạn, Quá hạn, Quá hạn trên 60 ngày), giải thích dễ hiểu. Excel của mình dùng dấu [\";\" / \",\"].", "url": "mot-ngay.html#p-mot-ngay-5"}, {"id": "p-mot-ngay-6", "page": "mot-ngay", "pageTitle": "Một ngày làm việc cùng AI: bốn nghề, từ sáng đến tối", "level": 0, "kind": "topic", "code": "ND6", "title": "Thuyết minh biến động, nói rõ 3 điều", "tags": ["ketoan"], "section": "💰 Một ngày của người làm kế toán – tài chính", "text": "Đính kèm chi phí tháng 8 và tháng 9 theo khoản mục (đã bỏ tên nhà cung cấp).\nMình muốn: thuyết minh 5 khoản biến động lớn nhất, mỗi khoản 2–3 câu, có số tuyệt đối và phần trăm.\nCông sức: nhanh gọn, bản nháp nội bộ.\nKiểm tra: cộng tổng từng tháng, so với dòng tổng trong file. Không rõ nguyên nhân thì để [CẦN BỔ SUNG LÝ DO], đừng tự nghĩ ra.", "url": "mot-ngay.html#p-mot-ngay-6"}, {"id": "p-mot-ngay-7", "page": "mot-ngay", "pageTitle": "Một ngày làm việc cùng AI: bốn nghề, từ sáng đến tối", "level": 0, "kind": "topic", "code": "ND7", "title": "Mỗi con số lấy ở đâu?", "tags": ["ketoan", "chung"], "section": "💰 Một ngày của người làm kế toán – tài chính", "text": "Liệt kê giúp mình mọi con số trong đoạn thuyết minh: số nào lấy từ file (dòng nào, cột nào), số nào bạn tính ra (ghi cách tính), số nào đã làm tròn.", "url": "mot-ngay.html#p-mot-ngay-7"}, {"id": "p-mot-ngay-8", "page": "mot-ngay", "pageTitle": "Một ngày làm việc cùng AI: bốn nghề, từ sáng đến tối", "level": 0, "kind": "topic", "code": "ND8", "title": "Quy chế thành hướng dẫn một trang", "tags": ["ketoan", "chung"], "section": "💰 Một ngày của người làm kế toán – tài chính", "text": "Đây là quy chế công tác phí của công ty mình. Viết hướng dẫn một trang cho nhân viên: các bước hoàn ứng, giấy tờ, hạn nộp, và mục \"Hay bị trả lại vì\" dựa trên các lỗi mình kể: [___]. Quy chế không nói thì ghi [HỎI KẾ TOÁN], đừng đoán.\n\n[Dán đoạn quy chế]", "url": "mot-ngay.html#p-mot-ngay-8"}, {"id": "p-mot-ngay-9", "page": "mot-ngay", "pageTitle": "Một ngày làm việc cùng AI: bốn nghề, từ sáng đến tối", "level": 0, "kind": "topic", "code": "ND9", "title": "Tập trước cuộc gặp", "tags": ["kinhdoanh"], "section": "🤝 Một ngày của người làm kinh doanh – CSKH", "text": "Lát nữa mình gặp [phòng hành chính một trường tư thục] lần đầu, họ cần [bàn ghế cho 10 phòng học]. Bạn đóng vai người phụ trách mua sắm, hỏi mình 3 câu khó nhất, từng câu một. Mình trả lời xong thì góp ý ngắn.", "url": "mot-ngay.html#p-mot-ngay-9"}, {"id": "p-mot-ngay-10", "page": "mot-ngay", "pageTitle": "Một ngày làm việc cùng AI: bốn nghề, từ sáng đến tối", "level": 0, "kind": "topic", "code": "ND10", "title": "Báo giá, nói rõ 3 điều", "tags": ["kinhdoanh"], "section": "🤝 Một ngày của người làm kinh doanh – CSKH", "text": "Mình cần báo giá cho [Trường A]: [danh mục, số lượng, đơn giá, chiết khấu được duyệt, VAT, thời gian giao].\nMình muốn: bảng báo giá và thư chào hàng ngắn nhấn vào [điều khách quan tâm nhất], gửi chiều nay.\nCông sức: kỹ ở phần tính toán, gọn ở phần thư.\nKiểm tra: tính tổng tiền bằng hai cách, báo mình có khớp không. Không thêm ưu đãi nào mình chưa nói.", "url": "mot-ngay.html#p-mot-ngay-10"}, {"id": "p-mot-ngay-11", "page": "mot-ngay", "pageTitle": "Một ngày làm việc cùng AI: bốn nghề, từ sáng đến tối", "level": 0, "kind": "topic", "code": "ND11", "title": "Chỗ nào bạn tự thêm?", "tags": ["kinhdoanh", "chung"], "section": "🤝 Một ngày của người làm kinh doanh – CSKH", "text": "Liệt kê mọi con số, thời hạn, bảo hành, ưu đãi trong báo giá và thư. Cái nào lấy từ thông tin mình đưa, cái nào bạn tự thêm? Xoá phần tự thêm, gửi lại bản sạch.", "url": "mot-ngay.html#p-mot-ngay-11"}, {"id": "p-mot-ngay-12", "page": "mot-ngay", "pageTitle": "Một ngày làm việc cùng AI: bốn nghề, từ sáng đến tối", "level": 0, "kind": "topic", "code": "ND12", "title": "Cập nhật cuối ngày", "tags": ["kinhdoanh"], "section": "🤝 Một ngày của người làm kinh doanh – CSKH", "text": "Hôm nay: [gặp Trường A, đã gửi báo giá; Khách B hẹn thanh toán thứ Sáu]. Ghi nhận giúp mình theo mẫu báo cáo tuần. Việc sáng mai cần nhắc thì liệt kê riêng.", "url": "mot-ngay.html#p-mot-ngay-12"}, {"id": "p-mot-ngay-13", "page": "mot-ngay", "pageTitle": "Một ngày làm việc cùng AI: bốn nghề, từ sáng đến tối", "level": 0, "kind": "topic", "code": "ND13", "title": "Bảng trắng thành việc của từng tổ", "tags": ["vanhanh"], "section": "🏗️ Một ngày của người làm vận hành – xây dựng", "text": "Đây là ảnh bảng trắng giao ca ở công trường. Chép lại thành danh sách việc của từng tổ: việc gì, ai phụ trách, xong trước mấy giờ. Chữ nào bạn đọc không chắc thì đánh dấu [?].", "url": "mot-ngay.html#p-mot-ngay-13"}, {"id": "p-mot-ngay-14", "page": "mot-ngay", "pageTitle": "Một ngày làm việc cùng AI: bốn nghề, từ sáng đến tối", "level": 0, "kind": "topic", "code": "ND14", "title": "Biên bản hàng về thiếu, móp", "tags": ["vanhanh"], "section": "🏗️ Một ngày của người làm vận hành – xây dựng", "text": "Đây là ảnh lô [thanh giằng kệ] vừa giao và phiếu giao hàng (đã che tên, số điện thoại). Mình đếm được [___] thanh, [___] thanh móp. Soạn biên bản ghi nhận: số theo phiếu, số thực nhận, hư hỏng thấy trong ảnh, đề nghị của bên nhận. Ảnh không đủ rõ thì ghi \"cần kiểm tra tại chỗ\".", "url": "mot-ngay.html#p-mot-ngay-14"}, {"id": "p-mot-ngay-15", "page": "mot-ngay", "pageTitle": "Một ngày làm việc cùng AI: bốn nghề, từ sáng đến tối", "level": 0, "kind": "topic", "code": "ND15", "title": "Xếp lại lịch, nói rõ 3 điều", "tags": ["vanhanh"], "section": "🏗️ Một ngày của người làm vận hành – xây dựng", "text": "Hàng bổ sung về sớm nhất [thứ Năm]. Đính kèm kế hoạch lắp đặt hiện tại.\nMình muốn: lịch mới để báo sếp chiều nay, cố giữ ngày bàn giao [___]; không giữ được thì nói rõ trễ mấy ngày, vì sao.\nCông sức: làm kỹ, tính cả việc nào làm song song được.\nKiểm tra: không tổ nào làm hai việc cùng lúc, không hạng mục nào bắt đầu khi việc trước nó chưa xong. Báo mình đã kiểm gì.", "url": "mot-ngay.html#p-mot-ngay-15"}, {"id": "p-mot-ngay-16", "page": "mot-ngay", "pageTitle": "Một ngày làm việc cùng AI: bốn nghề, từ sáng đến tối", "level": 0, "kind": "topic", "code": "ND16", "title": "Con số này lấy từ đâu?", "tags": ["vanhanh", "chung"], "section": "🏗️ Một ngày của người làm vận hành – xây dựng", "text": "Số [___] kg mỗi tầng kệ lấy từ tài liệu mình gửi (trang nào) hay từ kiến thức chung? Nói thẳng nhé. Việc an toàn, mình chỉ dùng số trong hồ sơ kỹ thuật của nhà sản xuất.", "url": "mot-ngay.html#p-mot-ngay-16"}, {"id": "p-mot-ngay-17", "page": "mot-ngay", "pageTitle": "Một ngày làm việc cùng AI: bốn nghề, từ sáng đến tối", "level": 0, "kind": "topic", "code": "ND17", "title": "Tủ lạnh còn gì, nấu nấy", "tags": ["doisong"], "section": "Buổi tối: cho chính mình", "text": "Đây là ảnh tủ lạnh nhà mình. Nhà có [2 người lớn, 1 bé 6 tuổi], mình có 30 phút. Gợi ý 2 món cho bữa tối, dùng tối đa đồ đang có.", "url": "mot-ngay.html#p-mot-ngay-17"}, {"id": "p-mot-ngay-18", "page": "mot-ngay", "pageTitle": "Một ngày làm việc cùng AI: bốn nghề, từ sáng đến tối", "level": 0, "kind": "topic", "code": "ND18", "title": "Mười lăm phút học mỗi tối", "tags": ["doisong"], "section": "Buổi tối: cho chính mình", "text": "Mình muốn [nói tiếng Anh tự tin hơn khi họp], mỗi tối có 15 phút. Hỏi mình 3 câu để biết mình đang ở đâu, rồi cho bài tập đầu tiên.", "url": "mot-ngay.html#p-mot-ngay-18"}, {"id": "p-thu-thach-7-ngay-1", "page": "thu-thach-7-ngay", "pageTitle": "Thử thách 7 ngày, 7 lần nhờ", "level": 0, "kind": "page", "code": "N1", "title": "Bạn giúp được mình việc gì?", "tags": ["chung"], "section": "Ngày 1 · \"Bạn giúp được mình việc gì?\"", "text": "Mình làm [nghề / vị trí] ở [loại công ty]. Mỗi ngày mình hay làm [kể 3–5 việc, ví dụ: soạn công văn, đối chiếu công nợ, trả lời email khách]. Việc mình thấy mất thời gian nhất là [___].\nBạn giúp được mình những việc gì? Gợi ý 10 việc, xếp từ dễ đến khó. Mỗi việc kèm một câu mở lời để mình copy thử ngay.", "url": "thu-thach-7-ngay.html#p-thu-thach-7-ngay-1"}, {"id": "p-thu-thach-7-ngay-2", "page": "thu-thach-7-ngay", "pageTitle": "Thử thách 7 ngày, 7 lần nhờ", "level": 0, "kind": "page", "code": "N2", "title": "Đóng vai người nhận khó tính", "tags": ["chung"], "section": "Ngày 2 · Nhờ góp ý thẳng", "text": "Mình sắp gửi [email / tin nhắn / văn bản] này cho [người nhận là ai, quan hệ thế nào]. Mục tiêu của mình là [___].\nBạn đóng vai người nhận khó tính nhất, đọc rồi nói thật 3 chỗ chưa ổn: chỗ nào dễ hiểu lầm, chỗ nào nghe cứng hoặc thiếu tôn trọng, chỗ nào thiếu thông tin. Xong viết lại giúp mình.\n\n[Dán nội dung đã che tên và số]", "url": "thu-thach-7-ngay.html#p-thu-thach-7-ngay-2"}, {"id": "p-thu-thach-7-ngay-3", "page": "thu-thach-7-ngay", "pageTitle": "Thử thách 7 ngày, 7 lần nhờ", "level": 0, "kind": "page", "code": "N3", "title": "Bạn giúp được gì với cái này?", "tags": ["chung", "doisong"], "section": "Ngày 3 · Chụp ảnh đống lộn xộn", "text": "Đây là ảnh [xấp hoá đơn / bảng trắng sau buổi họp / tủ lạnh nhà mình / bàn làm việc]. Bạn giúp được gì với cái này? Gợi ý 5 việc, rồi làm luôn việc bạn thấy hữu ích nhất.", "url": "thu-thach-7-ngay.html#p-thu-thach-7-ngay-3"}, {"id": "p-thu-thach-7-ngay-4", "page": "thu-thach-7-ngay", "pageTitle": "Thử thách 7 ngày, 7 lần nhờ", "level": 0, "kind": "page", "code": "N4", "title": "Giúp mình nghĩ cho rõ (nói bằng giọng)", "tags": ["chung", "doisong"], "section": "Ngày 4 · Nói chuyện bằng giọng nói 5 phút", "text": "Mình đang băn khoăn chuyện [___]. Bạn đừng vội khuyên nhé. Hỏi mình từng câu một để giúp mình nghĩ cho rõ. Trả lời ngắn thôi, như đang nói chuyện.", "url": "thu-thach-7-ngay.html#p-thu-thach-7-ngay-4"}, {"id": "p-thu-thach-7-ngay-5", "page": "thu-thach-7-ngay", "pageTitle": "Thử thách 7 ngày, 7 lần nhờ", "level": 0, "kind": "page", "code": "N5", "title": "Phỏng vấn mình để tạo trợ lý", "tags": ["chung"], "section": "Ngày 5 · Tạo Project hoặc Gem đầu tiên", "text": "Mình muốn tạo một trợ lý giúp mình [việc lặp lại, ví dụ: viết báo cáo tuần]. Bạn phỏng vấn mình từng câu một: mình là ai, làm việc này thế nào, thích kết quả ra sao, điều gì tuyệt đối không được làm. Khi đủ thông tin, tự viết giúp mình phần hướng dẫn để dán vào Project.", "url": "thu-thach-7-ngay.html#p-thu-thach-7-ngay-5"}, {"id": "p-thu-thach-7-ngay-6", "page": "thu-thach-7-ngay", "pageTitle": "Thử thách 7 ngày, 7 lần nhờ", "level": 0, "kind": "page", "code": "N6", "title": "Làm giúp mình một công cụ nhỏ", "tags": ["chung", "doisong"], "section": "Ngày 6 · Nhờ làm một công cụ hoặc trò chơi nhỏ", "text": "Mình muốn một [trò chơi ôn bảng cửu chương cho con 8 tuổi / bảng theo dõi chi tiêu gia đình / công cụ tính báo giá có chiết khấu và VAT] nhưng không biết mô tả thế nào cho đủ. Hỏi mình vài câu rồi làm luôn nhé. Giao diện tiếng Việt, chữ to, dễ dùng trên điện thoại.", "url": "thu-thach-7-ngay.html#p-thu-thach-7-ngay-6"}, {"id": "p-thu-thach-7-ngay-7", "page": "thu-thach-7-ngay", "pageTitle": "Thử thách 7 ngày, 7 lần nhờ", "level": 0, "kind": "page", "code": "N7", "title": "Việc táo bạo nhất", "tags": ["meta"], "section": "Ngày 7 · Việc táo bạo nhất", "text": "Mình muốn [việc táo bạo] mà chưa biết bắt đầu từ đâu, cũng không chắc AI làm được không. Bạn hỏi mình vài câu để hiểu rõ, rồi đề xuất cách làm từng bước. Phần nào bạn làm được ngay thì làm luôn, phần nào cần mình chuẩn bị thì nói rõ.", "url": "thu-thach-7-ngay.html#p-thu-thach-7-ngay-7"}, {"id": "p-thu-thach-7-ngay-8", "page": "thu-thach-7-ngay", "pageTitle": "Thử thách 7 ngày, 7 lần nhờ", "level": 0, "kind": "page", "code": "N8", "title": "Tổng kết 7 ngày làm bạn với AI", "tags": ["meta"], "section": "Nhìn lại 7 ngày", "text": "Đây là ghi chú 7 ngày mình thử nhờ AI, mỗi ngày một việc mới:\n[Dán ghi chú 7 ngày]\n\nGiúp mình nhìn lại:\n1. 3 cách nhờ hiệu quả nhất của mình, và vì sao hiệu quả.\n2. 2 thói quen chưa tốt mình nên bỏ.\n3. 1 việc nên biến thành quy trình dùng hằng tuần (gợi ý luôn cách làm).\n4. 5 việc nên thử trong tuần tới, xếp từ dễ đến khó.\nViết ngắn gọn, giọng như một người bạn đang động viên mình.", "url": "thu-thach-7-ngay.html#p-thu-thach-7-ngay-8"}, {"id": "p-tra-cuu-co-nguon-1", "page": "tra-cuu-co-nguon", "pageTitle": "Tra cứu có nguồn: tìm kiếm web và nghiên cứu sâu", "level": 0, "kind": "topic", "code": "TC1", "title": "Tra cứu có nguồn: câu mẫu", "tags": ["chung"], "section": "Cách nhờ", "text": "Tìm trên mạng giúp mình: [câu hỏi]. Mình cần thông tin này để [dùng vào việc gì, cho ai đọc].\nCông sức: [tra nhanh, 3–5 nguồn là đủ / tìm kỹ, đọc nhiều nguồn uy tín].\nCách kiểm: mỗi ý ghi link và ngày, ưu tiên trang chính thức. Chưa có nguồn thì ghi \"chưa có nguồn\", đừng đoán. Cuối cùng cho mình biết bạn đã kiểm được gì, chưa kiểm được gì.\nThiếu thông tin gì thì hỏi mình trước nhé.", "url": "tra-cuu-co-nguon.html#p-tra-cuu-co-nguon-1"}, {"id": "p-tra-cuu-co-nguon-2", "page": "tra-cuu-co-nguon", "pageTitle": "Tra cứu có nguồn: tìm kiếm web và nghiên cứu sâu", "level": 0, "kind": "topic", "code": "TC2", "title": "Kiểm tra hiệu lực văn bản", "tags": ["luat", "chung"], "section": "Làm thật", "text": "Mình đang dùng [tên và số hiệu văn bản] để [soạn hợp đồng / trả lời khách]. Tìm trên mạng giúp mình: văn bản này còn hiệu lực không? Đã bị sửa đổi, thay thế bởi văn bản nào, từ ngày nào? Dẫn link nguồn chính thức: Cơ sở dữ liệu quốc gia về văn bản pháp luật (vbpl.vn), Công báo, hoặc trang của cơ quan ban hành. Thông tin chỉ thấy ở trang tư nhân thì ghi rõ.", "url": "tra-cuu-co-nguon.html#p-tra-cuu-co-nguon-2"}, {"id": "p-tra-cuu-co-nguon-3", "page": "tra-cuu-co-nguon", "pageTitle": "Tra cứu có nguồn: tìm kiếm web và nghiên cứu sâu", "level": 0, "kind": "topic", "code": "TC3", "title": "So sánh nhà cung cấp", "tags": ["kinhdoanh", "vanhanh"], "section": "Làm thật", "text": "Công ty mình khoảng [số] người, ở [thành phố], cần nhà cung cấp [dịch vụ]. Tìm trên mạng 3–5 nơi, lập bảng theo [giá công bố, điều kiện hợp đồng, hỗ trợ], mỗi ô kèm nguồn và ngày. Không có thông tin công khai thì ghi \"không công bố\", đừng ước đoán. Gợi ý thêm 5 câu nên hỏi từng nơi.", "url": "tra-cuu-co-nguon.html#p-tra-cuu-co-nguon-3"}, {"id": "p-tra-cuu-co-nguon-4", "page": "tra-cuu-co-nguon", "pageTitle": "Tra cứu có nguồn: tìm kiếm web và nghiên cứu sâu", "level": 0, "kind": "topic", "code": "TC4", "title": "Hồ sơ nhanh về đối tác", "tags": ["kinhdoanh", "chung"], "section": "Làm thật", "text": "Chiều nay mình gặp [tên công ty], mã số thuế [___] nếu có, bàn về [nội dung]. Tìm trên mạng thông tin công khai: họ làm gì, quy mô, tin nổi bật 12 tháng gần đây, mỗi ý kèm link và ngày. Gọn nửa trang, thêm 5 câu nên hỏi. Thấy công ty trùng tên thì báo mình, đừng tự chọn.", "url": "tra-cuu-co-nguon.html#p-tra-cuu-co-nguon-4"}, {"id": "p-tra-cuu-co-nguon-5", "page": "tra-cuu-co-nguon", "pageTitle": "Tra cứu có nguồn: tìm kiếm web và nghiên cứu sâu", "level": 0, "kind": "topic", "code": "TC5", "title": "Giao đề bài nghiên cứu sâu", "tags": ["chung"], "section": "Làm thật", "text": "Mình cần báo cáo về [chủ đề] để [quyết định gì, trình ai]. Phạm vi: [khu vực, giai đoạn]. Ba câu mình quan tâm nhất: [___].\nCứ đọc kỹ, ưu tiên nguồn chính thức, hạn chế blog. Mọi con số kèm nguồn và ngày. Tách riêng điều nhiều nguồn xác nhận, điều chỉ một nguồn nói, chỗ các nguồn mâu thuẫn. Cuối cùng liệt kê câu chưa trả lời được.", "url": "tra-cuu-co-nguon.html#p-tra-cuu-co-nguon-5"}, {"id": "p-tra-cuu-co-nguon-6", "page": "tra-cuu-co-nguon", "pageTitle": "Tra cứu có nguồn: tìm kiếm web và nghiên cứu sâu", "level": 0, "kind": "topic", "code": "TC6", "title": "Rà lại nguồn", "tags": ["meta", "chung"], "section": "Dám hỏi lại", "text": "Rà lại nguồn bạn vừa dùng: nguồn nào chính thức, nguồn nào báo chí, nguồn nào blog hay trang tư nhân? Nguồn nào cũ hơn 12 tháng? Nguồn nào mâu thuẫn nhau, ở điểm nào? Ý nào chỉ dựa trên một nguồn?", "url": "tra-cuu-co-nguon.html#p-tra-cuu-co-nguon-6"}, {"id": "p-tra-cuu-co-nguon-7", "page": "tra-cuu-co-nguon", "pageTitle": "Tra cứu có nguồn: tìm kiếm web và nghiên cứu sâu", "level": 0, "kind": "topic", "code": "TC7", "title": "Bản đồ văn bản một vấn đề", "tags": ["luat"], "section": "Biến thể theo ngành", "text": "Tìm các văn bản pháp luật đang áp dụng về [vấn đề]. Lập bảng: số hiệu, cơ quan ban hành, ngày hiệu lực, tình trạng hiệu lực, link chính thức. Dự thảo để bảng riêng. Không chắc thì ghi \"cần kiểm tra\".", "url": "tra-cuu-co-nguon.html#p-tra-cuu-co-nguon-7"}, {"id": "p-tra-cuu-co-nguon-8", "page": "tra-cuu-co-nguon", "pageTitle": "Tra cứu có nguồn: tìm kiếm web và nghiên cứu sâu", "level": 0, "kind": "topic", "code": "TC8", "title": "Thay đổi mới về thuế, hoá đơn", "tags": ["ketoan"], "section": "Biến thể theo ngành", "text": "Tìm các thay đổi về [thuế GTGT / hoá đơn điện tử] có hiệu lực từ [kỳ] mà công ty [ngành] cần lưu ý. Mỗi thay đổi ghi nội dung, ngày hiệu lực, số hiệu và link văn bản gốc. Tin từ báo, blog thì ghi là nguồn thứ cấp.", "url": "tra-cuu-co-nguon.html#p-tra-cuu-co-nguon-8"}, {"id": "p-tra-cuu-co-nguon-9", "page": "tra-cuu-co-nguon", "pageTitle": "Tra cứu có nguồn: tìm kiếm web và nghiên cứu sâu", "level": 0, "kind": "topic", "code": "TC9", "title": "Cập nhật nhanh về đối thủ", "tags": ["kinhdoanh"], "section": "Biến thể theo ngành", "text": "Tìm thông tin công khai mới nhất về [2–3 đối thủ] mảng [sản phẩm]: sản phẩm mới, khuyến mãi đang chạy. Lập bảng kèm link và ngày. Cũ hơn 3 tháng thì đánh dấu \"có thể đã cũ\".", "url": "tra-cuu-co-nguon.html#p-tra-cuu-co-nguon-9"}, {"id": "p-tra-cuu-co-nguon-10", "page": "tra-cuu-co-nguon", "pageTitle": "Tra cứu có nguồn: tìm kiếm web và nghiên cứu sâu", "level": 0, "kind": "topic", "code": "TC10", "title": "Tìm công bố giá, quy chuẩn", "tags": ["vanhanh"], "section": "Biến thể theo ngành", "text": "Tìm công bố giá vật liệu xây dựng kỳ gần nhất của Sở Xây dựng [tỉnh, thành] cho [vật liệu], và quy chuẩn đang áp dụng cho [hạng mục]. Ghi kỳ, số hiệu, link chính thức. Không thấy thì nói không thấy, đừng lấy số từ trang rao bán.", "url": "tra-cuu-co-nguon.html#p-tra-cuu-co-nguon-10"}, {"id": "p-tu-dien-1", "page": "tu-dien", "pageTitle": "Từ điển AI cho dân văn phòng", "level": 0, "kind": "page", "code": "TD1", "title": "Giải thích một thuật ngữ AI", "tags": ["meta"], "section": "Gặp từ chưa có ở đây?", "text": "Giải thích giúp mình từ \"[thuật ngữ]\" như đang nói với một người làm [ngành của bạn] không rành kỹ thuật. Tối đa 3 câu, kèm 1 ví dụ gần với công việc văn phòng. Nếu từ này có nhiều nghĩa tuỳ công cụ, nói rõ giúp mình.", "url": "tu-dien.html#p-tu-dien-1"}, {"id": "p-_thu-vien-them-1", "page": "_thu-vien-them", "pageTitle": "Prompt bổ sung", "level": 0, "kind": "prompts", "code": "VB1", "title": "Soạn công văn trả lời cơ quan nhà nước", "tags": ["luat", "chung"], "section": "Email & văn bản", "text": "Công ty mình vừa nhận công văn của [cơ quan] về việc [nội dung], yêu cầu [giải trình / cung cấp hồ sơ] trước ngày [___]. Quan điểm của công ty là [___], hồ sơ mình có thể cung cấp gồm [___].\nSoạn giúp mình công văn trả lời đúng thể thức văn bản hành chính: số, ký hiệu, trích yếu, kính gửi, nội dung, nơi nhận. Giọng cầu thị, rõ ràng, không nhận lỗi những việc chưa xác định. Chỗ nào cần mình điền thêm thì để trong [ngoặc vuông].\nNếu cần thêm thông tin thì hỏi mình trước nhé.", "url": "thu-vien-prompt.html#p-_thu-vien-them-1"}, {"id": "p-_thu-vien-them-2", "page": "_thu-vien-them", "pageTitle": "Prompt bổ sung", "level": 0, "kind": "prompts", "code": "VB2", "title": "Viết tờ trình xin duyệt", "tags": ["chung", "ketoan"], "section": "Email & văn bản", "text": "Mình cần trình [Giám đốc / Hội đồng quản trị] duyệt [nội dung: mua thiết bị, chi phí phát sinh, thay đổi nhà cung cấp…]. Lý do: [___]. Chi phí dự kiến: [___]. Phương án thay thế mình đã cân nhắc: [___].\nViết giúp mình tờ trình gồm: sự cần thiết, nội dung đề xuất, chi phí và nguồn kinh phí, so sánh phương án, kiến nghị. Ngắn gọn, sếp đọc 2 phút là quyết được.\nNếu cần thêm thông tin thì hỏi mình trước nhé.", "url": "thu-vien-prompt.html#p-_thu-vien-them-2"}, {"id": "p-_thu-vien-them-3", "page": "_thu-vien-them", "pageTitle": "Prompt bổ sung", "level": 0, "kind": "prompts", "code": "VB3", "title": "Email nhắc thanh toán lần 2", "tags": ["ketoan", "kinhdoanh"], "section": "Email & văn bản", "text": "Khách hàng [tên công ty] đang quá hạn thanh toán [số] ngày với số tiền [___], hoá đơn số [___]. Mình đã nhắc lần 1 vào ngày [___] nhưng chưa thấy phản hồi. Đây là khách [lâu năm / mới], mình muốn giữ quan hệ.\nViết email nhắc lần 2: lịch sự nhưng cương quyết, nêu rõ số tiền, hạn mới, cách thanh toán, và bước tiếp theo nếu vẫn chưa thanh toán. Cho mình 2 phiên bản: mềm và cứng hơn một chút.", "url": "thu-vien-prompt.html#p-_thu-vien-them-3"}, {"id": "p-_thu-vien-them-4", "page": "_thu-vien-them", "pageTitle": "Prompt bổ sung", "level": 0, "kind": "prompts", "code": "VB4", "title": "Từ chối khéo một đề nghị", "tags": ["chung", "kinhdoanh"], "section": "Email & văn bản", "text": "Mình cần từ chối [đề nghị: giảm giá thêm / nhận thêm việc / tham gia dự án] của [ai, quan hệ thế nào]. Lý do thật là [___], nhưng mình muốn giữ quan hệ tốt và nếu được thì đưa ra một phương án khác: [___].\nViết giúp mình [email / tin nhắn Zalo] ngắn, chân thành, không vòng vo, không nghe như lấy cớ.", "url": "thu-vien-prompt.html#p-_thu-vien-them-4"}, {"id": "p-_thu-vien-them-5", "page": "_thu-vien-them", "pageTitle": "Prompt bổ sung", "level": 0, "kind": "prompts", "code": "VB5", "title": "Thông báo nội bộ dễ hiểu", "tags": ["vanhanh", "chung"], "section": "Email & văn bản", "text": "Mình cần thông báo tới [toàn công ty / cư dân / nhân viên ca đêm] về việc [nội dung thay đổi], áp dụng từ [ngày]. Người đọc cần biết: [điều gì thay đổi, ảnh hưởng gì đến họ, họ phải làm gì, hỏi ai].\nViết thông báo ngắn, dễ đọc trên điện thoại: tiêu đề rõ, gạch đầu dòng, không thuật ngữ khó. Thêm một bản rút gọn 3 dòng để gửi qua Zalo.", "url": "thu-vien-prompt.html#p-_thu-vien-them-5"}, {"id": "p-_thu-vien-them-6", "page": "_thu-vien-them", "pageTitle": "Prompt bổ sung", "level": 0, "kind": "prompts", "code": "VB6", "title": "Viết lại cho ngắn và rõ", "tags": ["chung"], "section": "Email & văn bản", "text": "Đoạn văn dưới đây mình viết dài và rối quá. Viết lại giúp mình ngắn còn khoảng một nửa, giữ đủ ý chính, câu ngắn, dễ hiểu. Sau đó liệt kê những ý bạn đã bỏ để mình xem có cần giữ lại ý nào không.\n\n[Dán đoạn văn]", "url": "thu-vien-prompt.html#p-_thu-vien-them-6"}, {"id": "p-_thu-vien-them-7", "page": "_thu-vien-them", "pageTitle": "Prompt bổ sung", "level": 0, "kind": "prompts", "code": "VB7", "title": "Trả lời khiếu nại của khách", "tags": ["kinhdoanh"], "section": "Email & văn bản", "text": "Khách hàng [tên hoặc mô tả] khiếu nại về [vấn đề]. Sự thật là [phía mình sai ở đâu, phía khách hiểu lầm ở đâu]. Công ty có thể [đền bù / sửa / giải thích] như sau: [___].\nViết thư trả lời: xin lỗi đúng chỗ cần xin lỗi, giải thích ngắn không đổ lỗi, đưa giải pháp kèm mốc thời gian. Sau đó đóng vai chính khách hàng đó, đọc lại và nói thật bạn còn bực ở chỗ nào.", "url": "thu-vien-prompt.html#p-_thu-vien-them-7"}, {"id": "p-_thu-vien-them-8", "page": "_thu-vien-them", "pageTitle": "Prompt bổ sung", "level": 0, "kind": "prompts", "code": "PL1", "title": "Rà soát hợp đồng theo phía mình", "tags": ["luat"], "section": "Tài liệu & pháp lý", "text": "Mình là [bên mua / bên bán / bên thuê…] trong hợp đồng đính kèm (đã che tên và số). Rà soát giúp mình:\n1. Nghĩa vụ chính và thời hạn của mỗi bên.\n2. Điều khoản bất lợi cho phía mình, xếp theo mức rủi ro.\n3. Điều khoản mơ hồ, có thể hiểu theo nhiều cách.\n4. Những gì thường có trong loại hợp đồng này mà ở đây còn thiếu.\nVới mỗi ý, trích nguyên văn và ghi số Điều. Chỗ nào là bạn suy luận thì ghi rõ.", "url": "thu-vien-prompt.html#p-_thu-vien-them-8"}, {"id": "p-_thu-vien-them-9", "page": "_thu-vien-them", "pageTitle": "Prompt bổ sung", "level": 0, "kind": "prompts", "code": "PL2", "title": "So sánh hai phiên bản văn bản", "tags": ["luat", "chung"], "section": "Tài liệu & pháp lý", "text": "Mình gửi hai phiên bản của cùng một [hợp đồng / quy chế / văn bản]: bản cũ và bản mới. Lập bảng so sánh gồm: Điều, Bản cũ, Bản mới, Thay đổi có ý nghĩa gì với [phía mình]. Chỉ liệt kê những chỗ thay đổi về nội dung, bỏ qua lỗi chính tả hay đổi cách trình bày. Cuối bảng, nêu 3 thay đổi quan trọng nhất mình cần chú ý.", "url": "thu-vien-prompt.html#p-_thu-vien-them-9"}, {"id": "p-_thu-vien-them-10", "page": "_thu-vien-them", "pageTitle": "Prompt bổ sung", "level": 0, "kind": "prompts", "code": "PL3", "title": "Giải thích văn bản pháp luật cho người không chuyên", "tags": ["luat", "chung"], "section": "Tài liệu & pháp lý", "text": "Đây là [tên văn bản / đoạn trích]. Giải thích giúp mình cho [nhân viên kinh doanh / kế toán / ban giám đốc] hiểu: văn bản này quy định gì, áp dụng cho ai, từ khi nào, công ty mình cần làm gì khác đi. Dùng lời thường, có ví dụ.\nChỉ dựa trên nội dung mình gửi. Chỗ nào văn bản không nói rõ thì ghi \"văn bản không đề cập\", đừng đoán.", "url": "thu-vien-prompt.html#p-_thu-vien-them-10"}, {"id": "p-_thu-vien-them-11", "page": "_thu-vien-them", "pageTitle": "Prompt bổ sung", "level": 0, "kind": "prompts", "code": "PL4", "title": "Lập checklist hồ sơ", "tags": ["luat", "vanhanh"], "section": "Tài liệu & pháp lý", "text": "Mình cần chuẩn bị hồ sơ cho [thủ tục / gói thầu / nghiệm thu / ký hợp đồng với nhà cung cấp mới]. Dựa trên [tài liệu hướng dẫn đính kèm / yêu cầu sau: ___], lập giúp mình checklist gồm: tên giấy tờ, số bản, bản gốc hay bản sao, ai chuẩn bị, hạn chót. Đánh dấu những giấy tờ hay bị thiếu hoặc mất nhiều thời gian nhất.", "url": "thu-vien-prompt.html#p-_thu-vien-them-11"}, {"id": "p-_thu-vien-them-12", "page": "_thu-vien-them", "pageTitle": "Prompt bổ sung", "level": 0, "kind": "prompts", "code": "PL5", "title": "Tóm tắt hồ sơ mời thầu", "tags": ["kinhdoanh", "vanhanh"], "section": "Tài liệu & pháp lý", "text": "Đây là hồ sơ mời thầu [tên gói thầu]. Tóm tắt giúp mình trên 1 trang: yêu cầu bắt buộc (năng lực, kinh nghiệm, tài chính), tiêu chí đánh giá, các mốc thời gian quan trọng, bảo lãnh dự thầu. Rồi liệt kê những điểm công ty mình có thể yếu, biết rằng công ty mình [mô tả ngắn năng lực].\nMỗi ý ghi số mục hoặc số trang để mình đối chiếu.", "url": "thu-vien-prompt.html#p-_thu-vien-them-12"}, {"id": "p-_thu-vien-them-13", "page": "_thu-vien-them", "pageTitle": "Prompt bổ sung", "level": 0, "kind": "prompts", "code": "PL6", "title": "Soạn phụ lục sửa đổi hợp đồng", "tags": ["luat"], "section": "Tài liệu & pháp lý", "text": "Hai bên muốn sửa hợp đồng số [___] ở các điểm sau: [liệt kê: đổi thời hạn giao hàng, đổi giá, thêm hạng mục…]. Các điều khoản khác giữ nguyên.\nSoạn giúp mình phụ lục sửa đổi: căn cứ, nội dung sửa đổi ghi rõ \"Điều X được sửa thành…\", hiệu lực, số bản. Thêm 3 lưu ý pháp lý mình nên kiểm tra trước khi ký. Nếu cần thêm thông tin thì hỏi mình trước nhé.", "url": "thu-vien-prompt.html#p-_thu-vien-them-13"}, {"id": "p-_thu-vien-them-14", "page": "_thu-vien-them", "pageTitle": "Prompt bổ sung", "level": 0, "kind": "prompts", "code": "SL1", "title": "Viết công thức Excel bằng tiếng Việt", "tags": ["chung", "ketoan"], "section": "Số liệu & Excel", "text": "Bảng của mình: cột A là [___], cột B là [___], cột C là [___], dữ liệu từ dòng 2 đến dòng [___]. Mình muốn [mô tả điều muốn tính, ví dụ: tổng tiền theo từng nhà cung cấp trong tháng 9].\nViết công thức giúp mình và giải thích từng phần thật dễ hiểu. Excel của mình dùng dấu [\";\" / \",\"] để ngăn cách. Nếu có cách đơn giản hơn công thức (như PivotTable) thì gợi ý luôn.", "url": "thu-vien-prompt.html#p-_thu-vien-them-14"}, {"id": "p-_thu-vien-them-15", "page": "_thu-vien-them", "pageTitle": "Prompt bổ sung", "level": 0, "kind": "prompts", "code": "SL2", "title": "Đối chiếu công nợ", "tags": ["ketoan"], "section": "Số liệu & Excel", "text": "Mình có hai bảng: sổ chi tiết công nợ của công ty và biên bản đối chiếu khách hàng [mã KH] gửi về (đã che tên). Đối chiếu giúp mình từng hoá đơn và từng lần thanh toán: khớp, lệch số tiền, có bên này mà không có bên kia. Lập bảng chênh lệch, đoán nguyên nhân có thể (ghi rõ là đoán), và soạn sẵn email gửi khách để xác nhận các khoản lệch.", "url": "thu-vien-prompt.html#p-_thu-vien-them-15"}, {"id": "p-_thu-vien-them-16", "page": "_thu-vien-them", "pageTitle": "Prompt bổ sung", "level": 0, "kind": "prompts", "code": "SL3", "title": "Giải thích biến động so với kỳ trước", "tags": ["ketoan"], "section": "Số liệu & Excel", "text": "Đây là số liệu [chi phí / doanh thu] kỳ này và kỳ trước theo từng khoản mục. Chỉ ra 5 khoản biến động lớn nhất (cả số tuyệt đối và phần trăm), rồi viết đoạn thuyết minh ngắn cho từng khoản. Chỗ nào bạn không biết nguyên nhân thì để [CẦN BỔ SUNG LÝ DO] cho mình điền, đừng tự nghĩ ra lý do.", "url": "thu-vien-prompt.html#p-_thu-vien-them-16"}, {"id": "p-_thu-vien-them-17", "page": "_thu-vien-them", "pageTitle": "Prompt bổ sung", "level": 0, "kind": "prompts", "code": "SL4", "title": "Dọn sạch một danh sách", "tags": ["chung"], "section": "Số liệu & Excel", "text": "Đây là danh sách [khách hàng / nhà cung cấp / nhân sự] gõ tay qua nhiều năm, khá lộn xộn. Dọn giúp mình: gộp tên viết khác nhau của cùng một đơn vị, chuẩn hoá số điện thoại và ngày tháng, đánh dấu dòng trùng và dòng thiếu thông tin. Cho mình tải file đã sửa, kèm bảng ghi lại bạn đã sửa những gì.", "url": "thu-vien-prompt.html#p-_thu-vien-them-17"}, {"id": "p-_thu-vien-them-18", "page": "_thu-vien-them", "pageTitle": "Prompt bổ sung", "level": 0, "kind": "prompts", "code": "SL5", "title": "Tìm điểm bất thường", "tags": ["ketoan", "vanhanh"], "section": "Số liệu & Excel", "text": "Đây là bảng [chi phí / nhật ký kho / chấm công] tháng [___]. Tìm giúp mình những điểm bất thường: số tiền lớn khác thường, giao dịch trùng, ngày lạ (cuối tuần, ngày lễ), người đề nghị lặp lại nhiều. Với mỗi điểm, nói vì sao bạn thấy bất thường và mình nên kiểm tra gì. Đừng kết luận ai sai, chỉ đánh dấu để mình xem.", "url": "thu-vien-prompt.html#p-_thu-vien-them-18"}, {"id": "p-_thu-vien-them-19", "page": "_thu-vien-them", "pageTitle": "Prompt bổ sung", "level": 0, "kind": "prompts", "code": "SL6", "title": "Từ bảng số đến nhận xét cho sếp", "tags": ["chung", "kinhdoanh"], "section": "Số liệu & Excel", "text": "Đây là bảng số liệu [doanh số / tiến độ / chi phí] tuần này. Viết giúp mình 5 dòng nhận xét cho Giám đốc: điều tốt nhất, điều đáng lo nhất, xu hướng so với tuần trước, một việc cần sếp quyết định, một đề xuất. Mỗi nhận xét phải kèm con số cụ thể từ bảng. Sau đó đóng vai sếp khó tính, hỏi vặn mình 2 câu.", "url": "thu-vien-prompt.html#p-_thu-vien-them-19"}, {"id": "p-_thu-vien-them-20", "page": "_thu-vien-them", "pageTitle": "Prompt bổ sung", "level": 0, "kind": "prompts", "code": "HK1", "title": "Biên bản họp từ ghi chú vội", "tags": ["chung"], "section": "Họp & kế hoạch", "text": "Đây là ghi chú mình viết vội trong cuộc họp [tên cuộc họp] ngày [___], thành phần gồm [___]. Viết lại thành biên bản: nội dung đã thống nhất, việc cần làm (ai làm, hạn khi nào), vấn đề còn treo. Chỗ nào ghi chú không rõ ai nhận việc hoặc hạn khi nào thì đánh dấu [CẦN XÁC NHẬN], đừng tự điền.\n\n[Dán ghi chú]", "url": "thu-vien-prompt.html#p-_thu-vien-them-20"}, {"id": "p-_thu-vien-them-21", "page": "_thu-vien-them", "pageTitle": "Prompt bổ sung", "level": 0, "kind": "prompts", "code": "HK2", "title": "Lên kế hoạch tuần", "tags": ["chung"], "section": "Họp & kế hoạch", "text": "Tuần này mình có các việc sau: [liệt kê, kèm hạn nếu có]. Lịch cố định: [các cuộc họp, buổi đi công tác]. Mình làm việc tốt nhất vào [buổi sáng / buổi chiều].\nSắp xếp giúp mình kế hoạch tuần: việc nào làm trước, chia vào từng ngày, chừa thời gian cho việc phát sinh. Chỉ ra việc nào có thể nhờ AI làm nháp, việc nào nên giao hoặc bỏ.", "url": "thu-vien-prompt.html#p-_thu-vien-them-21"}, {"id": "p-_thu-vien-them-22", "page": "_thu-vien-them", "pageTitle": "Prompt bổ sung", "level": 0, "kind": "prompts", "code": "HK3", "title": "Viết OKR cho quý", "tags": ["chung"], "section": "Họp & kế hoạch", "text": "Mình là [vị trí] ở [phòng ban]. Quý tới, công ty ưu tiên [___], còn phòng mình muốn [___]. Giúp mình viết 2–3 mục tiêu (Objective) truyền cảm hứng, mỗi mục tiêu có 2–4 kết quả then chốt (Key Result) đo được bằng con số. Sau đó chỉ ra kết quả nào đang mơ hồ hoặc khó đo, và gợi ý sửa.\nHỏi mình vài câu trước nếu bạn cần hiểu thêm về phòng mình nhé.", "url": "thu-vien-prompt.html#p-_thu-vien-them-22"}, {"id": "p-_thu-vien-them-23", "page": "_thu-vien-them", "pageTitle": "Prompt bổ sung", "level": 0, "kind": "prompts", "code": "HK4", "title": "Chuẩn bị cho một cuộc họp khó", "tags": ["chung"], "section": "Họp & kế hoạch", "text": "Tuần sau mình họp với [ai] về [vấn đề]. Mình muốn đạt được [___], còn phía bên kia có thể muốn [___]. Giúp mình chuẩn bị: mục tiêu cuộc họp, 3 luận điểm chính, 5 câu hỏi khó họ có thể hỏi và cách trả lời, điểm mình có thể nhượng bộ và điểm không được nhượng. Sau đó đóng vai họ để mình tập nói thử.", "url": "thu-vien-prompt.html#p-_thu-vien-them-23"}, {"id": "p-_thu-vien-them-24", "page": "_thu-vien-them", "pageTitle": "Prompt bổ sung", "level": 0, "kind": "prompts", "code": "HK5", "title": "Chia việc lớn thành đầu việc nhỏ", "tags": ["vanhanh", "chung"], "section": "Họp & kế hoạch", "text": "Mình phụ trách [dự án / sự kiện / chuyển văn phòng], hạn hoàn thành [ngày], nhóm có [số người, vai trò]. Chia giúp mình thành các đầu việc nhỏ, mỗi việc làm xong trong 1–2 ngày, có người phụ trách gợi ý, thứ tự trước sau, và mốc kiểm tra. Đánh dấu những việc dễ bị trễ nhất. Xuất thành bảng để mình dán vào Excel.", "url": "thu-vien-prompt.html#p-_thu-vien-them-24"}, {"id": "p-_thu-vien-them-25", "page": "_thu-vien-them", "pageTitle": "Prompt bổ sung", "level": 0, "kind": "prompts", "code": "HK6", "title": "Bộ câu hỏi phỏng vấn tuyển dụng", "tags": ["chung"], "section": "Họp & kế hoạch", "text": "Mình cần phỏng vấn ứng viên vị trí [___], yêu cầu chính: [kỹ năng, kinh nghiệm]. Văn hoá nhóm mình: [___].\nSoạn giúp mình 10 câu hỏi phỏng vấn: kiểm tra chuyên môn, kỹ năng xử lý tình huống, độ hợp văn hoá. Với mỗi câu, ghi câu trả lời tốt trông thế nào và dấu hiệu đáng lo. Kèm một bảng chấm điểm đơn giản để những người cùng phỏng vấn chấm cho thống nhất.", "url": "thu-vien-prompt.html#p-_thu-vien-them-25"}, {"id": "p-_thu-vien-them-26", "page": "_thu-vien-them", "pageTitle": "Prompt bổ sung", "level": 0, "kind": "prompts", "code": "HK7", "title": "Viết nhận xét đánh giá nhân viên", "tags": ["chung"], "section": "Họp & kế hoạch", "text": "Mình cần viết nhận xét đánh giá [6 tháng / cuối năm] cho một thành viên trong nhóm (không ghi tên). Điểm mạnh mình quan sát được: [ví dụ cụ thể]. Điểm cần cải thiện: [ví dụ cụ thể]. Mục tiêu kỳ tới: [___].\nViết giúp mình bản nhận xét công bằng, cụ thể, dựa trên hành vi chứ không phán xét con người, giọng động viên. Gợi ý thêm 3 câu mình nên nói khi gặp trực tiếp.", "url": "thu-vien-prompt.html#p-_thu-vien-them-26"}, {"id": "p-_thu-vien-them-27", "page": "_thu-vien-them", "pageTitle": "Prompt bổ sung", "level": 0, "kind": "prompts", "code": "TT1", "title": "Dàn ý bài thuyết trình", "tags": ["chung"], "section": "Thuyết trình & truyền thông", "text": "Mình cần thuyết trình [chủ đề] trong [số] phút cho [ai nghe, họ quan tâm gì]. Điều mình muốn họ nhớ nhất sau buổi là [___].\nGiúp mình dàn ý: mở đầu gây chú ý, 3 ý chính, mỗi ý có ví dụ hoặc con số, kết thúc với lời kêu gọi rõ ràng. Gợi ý nội dung cho từng slide, mỗi slide không quá 15 chữ.", "url": "thu-vien-prompt.html#p-_thu-vien-them-27"}, {"id": "p-_thu-vien-them-28", "page": "_thu-vien-them", "pageTitle": "Prompt bổ sung", "level": 0, "kind": "prompts", "code": "TT2", "title": "Luyện trả lời câu hỏi khó", "tags": ["chung"], "section": "Thuyết trình & truyền thông", "text": "Mình sắp trình bày [nội dung] trước [ai]. Bạn đóng vai người nghe khó tính nhất trong phòng, hỏi mình từng câu một, mỗi lần một câu. Sau mỗi câu trả lời của mình, chấm điểm 1–10 và gợi ý cách trả lời gọn, thuyết phục hơn. Hỏi tổng cộng 5 câu nhé.", "url": "thu-vien-prompt.html#p-_thu-vien-them-28"}, {"id": "p-_thu-vien-them-29", "page": "_thu-vien-them", "pageTitle": "Prompt bổ sung", "level": 0, "kind": "prompts", "code": "TT3", "title": "Báo giá kèm thư chào hàng", "tags": ["kinhdoanh"], "section": "Thuyết trình & truyền thông", "text": "Khách [mô tả: loại doanh nghiệp, nhu cầu] hỏi báo giá [sản phẩm / dịch vụ]. Thông tin: [danh mục, số lượng, đơn giá, chiết khấu, VAT, thời gian giao, hiệu lực báo giá].\nLàm giúp mình bảng báo giá rõ ràng, tự tính thành tiền, chiết khấu, VAT, tổng cộng, kèm một thư chào hàng ngắn nhấn vào lợi ích khách quan tâm nhất. Kiểm tra lại các phép tính và ghi rõ cách tính.", "url": "thu-vien-prompt.html#p-_thu-vien-them-29"}, {"id": "p-_thu-vien-them-30", "page": "_thu-vien-them", "pageTitle": "Prompt bổ sung", "level": 0, "kind": "prompts", "code": "TT4", "title": "Bài đăng giới thiệu sản phẩm", "tags": ["kinhdoanh"], "section": "Thuyết trình & truyền thông", "text": "Viết giúp mình 3 phiên bản bài đăng [Facebook / LinkedIn / Zalo OA] giới thiệu [sản phẩm, dịch vụ] cho [khách hàng mục tiêu]. Điểm khác biệt: [___]. Ưu đãi: [___].\nMỗi bản một phong cách: kể chuyện, ngắn gọn thẳng vào lợi ích, hỏi đáp. Không phóng đại, không dùng từ \"tốt nhất\", \"số 1\" nếu không có căn cứ.", "url": "thu-vien-prompt.html#p-_thu-vien-them-30"}, {"id": "p-_thu-vien-them-31", "page": "_thu-vien-them", "pageTitle": "Prompt bổ sung", "level": 0, "kind": "prompts", "code": "TT5", "title": "Kịch bản chăm sóc khách hàng qua điện thoại", "tags": ["kinhdoanh"], "section": "Thuyết trình & truyền thông", "text": "Mình cần kịch bản gọi điện cho [khách mới mua hàng / khách lâu không quay lại / khách vừa phàn nàn] của công ty [ngành]. Mục tiêu cuộc gọi: [___].\nViết kịch bản gồm: câu chào, câu hỏi mở, cách xử lý 4 phản ứng thường gặp (bận, không quan tâm, đang bực, hỏi giá), cách kết thúc. Lời nói tự nhiên như người thật, không đọc như máy.", "url": "thu-vien-prompt.html#p-_thu-vien-them-31"}, {"id": "p-_thu-vien-them-32", "page": "_thu-vien-them", "pageTitle": "Prompt bổ sung", "level": 0, "kind": "prompts", "code": "TT6", "title": "Viết lại cho từng đối tượng", "tags": ["chung"], "section": "Thuyết trình & truyền thông", "text": "Đây là nội dung về [chủ đề, ví dụ: chính sách công tác phí mới]. Viết lại thành 3 phiên bản: một cho Ban giám đốc (ngắn, tập trung tác động và chi phí), một cho nhân viên (dễ hiểu, họ cần làm gì), một cho khách hàng hoặc đối tác (nếu liên quan, lịch sự, ngắn). Giữ đúng thông tin, chỉ đổi cách nói.\n\n[Dán nội dung]", "url": "thu-vien-prompt.html#p-_thu-vien-them-32"}, {"id": "p-_thu-vien-them-33", "page": "_thu-vien-them", "pageTitle": "Prompt bổ sung", "level": 0, "kind": "prompts", "code": "PT1", "title": "Luyện tiếng Anh theo tình huống công việc", "tags": ["chung"], "section": "Học & phát triển bản thân", "text": "Mình muốn luyện tiếng Anh để [họp với đối tác / viết email cho khách nước ngoài / phỏng vấn]. Trình độ của mình khoảng [mới bắt đầu / giao tiếp cơ bản / khá]. Bạn đóng vai [đối tác / khách hàng / người phỏng vấn], nói chuyện với mình bằng tiếng Anh đơn giản, mỗi lần 1–2 câu. Sau mỗi câu mình trả lời, sửa lỗi của mình bằng tiếng Việt và gợi ý cách nói tự nhiên hơn.", "url": "thu-vien-prompt.html#p-_thu-vien-them-33"}, {"id": "p-_thu-vien-them-34", "page": "_thu-vien-them", "pageTitle": "Prompt bổ sung", "level": 0, "kind": "prompts", "code": "PT2", "title": "Sửa email tiếng Anh và giải thích lỗi", "tags": ["chung"], "section": "Học & phát triển bản thân", "text": "Đây là email tiếng Anh mình viết gửi [ai] về [việc gì]. Sửa giúp mình cho tự nhiên và chuyên nghiệp, giữ đúng ý. Sau đó lập bảng các lỗi mình hay mắc (ngữ pháp, từ dùng chưa hợp, câu dịch kiểu tiếng Việt), giải thích bằng tiếng Việt để lần sau mình tự tránh được.\n\n[Dán email]", "url": "thu-vien-prompt.html#p-_thu-vien-them-34"}, {"id": "p-_thu-vien-them-35", "page": "_thu-vien-them", "pageTitle": "Prompt bổ sung", "level": 0, "kind": "prompts", "code": "PT3", "title": "Lộ trình học nhanh một chủ đề mới", "tags": ["chung"], "section": "Học & phát triển bản thân", "text": "Mình cần hiểu về [chủ đề, ví dụ: hoá đơn điện tử, quản trị dự án, phân tích báo cáo tài chính] đủ để [mục tiêu cụ thể] trong 2 tuần, mỗi ngày học được khoảng [số] phút.\nLập giúp mình lộ trình theo ngày: học gì, tài liệu loại gì nên tìm, bài tập nhỏ để tự kiểm tra. Bắt đầu bằng việc hỏi mình 3 câu để biết mình đang ở đâu.", "url": "thu-vien-prompt.html#p-_thu-vien-them-35"}, {"id": "p-_thu-vien-them-36", "page": "_thu-vien-them", "pageTitle": "Prompt bổ sung", "level": 0, "kind": "prompts", "code": "PT4", "title": "Chuẩn bị phỏng vấn hoặc đàm phán lương", "tags": ["chung"], "section": "Học & phát triển bản thân", "text": "Mình sắp [phỏng vấn vị trí ___ / nói chuyện tăng lương với sếp]. Những gì mình đã làm được: [kết quả cụ thể, con số]. Điều mình mong muốn: [___].\nGiúp mình chuẩn bị: cách kể thành tích ngắn gọn, thuyết phục; 5 câu khó có thể bị hỏi và gợi ý trả lời; những câu nên tránh nói. Rồi đóng vai [người phỏng vấn / sếp] để mình tập.", "url": "thu-vien-prompt.html#p-_thu-vien-them-36"}, {"id": "p-_thu-vien-them-37", "page": "_thu-vien-them", "pageTitle": "Prompt bổ sung", "level": 0, "kind": "prompts", "code": "PT5", "title": "Tóm tắt sách để áp dụng ngay", "tags": ["chung"], "section": "Học & phát triển bản thân", "text": "Mình vừa đọc (hoặc muốn đọc) cuốn [tên sách] của [tác giả]. Tóm tắt giúp mình các ý chính, rồi gợi ý 5 cách áp dụng cụ thể cho công việc [nghề của bạn] và đời sống. Nếu bạn không chắc về nội dung cuốn sách thì nói rõ, đừng đoán.", "url": "thu-vien-prompt.html#p-_thu-vien-them-37"}, {"id": "p-_thu-vien-them-38", "page": "_thu-vien-them", "pageTitle": "Prompt bổ sung", "level": 0, "kind": "prompts", "code": "DS1", "title": "Kế hoạch du lịch gia đình", "tags": ["doisong"], "section": "Đời sống & gia đình", "text": "Nhà mình [số người, độ tuổi các con, ông bà có đi không] muốn đi [địa điểm] [số] ngày vào [thời gian], ngân sách khoảng [___]. Nhà mình thích [biển / ăn uống / thiên nhiên / nghỉ ngơi nhẹ nhàng], không thích [___].\nLên giúp mình lịch trình từng ngày, có thời gian nghỉ cho trẻ nhỏ, danh sách đồ cần mang, và các việc cần đặt trước. Giá vé, giờ mở cửa thì ghi chú để mình tự kiểm tra lại.\nNếu cần thêm thông tin thì hỏi mình trước nhé.", "url": "thu-vien-prompt.html#p-_thu-vien-them-38"}, {"id": "p-_thu-vien-them-39", "page": "_thu-vien-them", "pageTitle": "Prompt bổ sung", "level": 0, "kind": "prompts", "code": "DS2", "title": "Thực đơn tuần và danh sách đi chợ", "tags": ["doisong"], "section": "Đời sống & gia đình", "text": "Nhà mình [số người], có [trẻ nhỏ / người lớn tuổi / người ăn kiêng / dị ứng ___]. Mình có khoảng [số] phút nấu mỗi tối, thích món [miền Bắc / miền Nam / đa dạng].\nLên thực đơn 7 ngày cho bữa tối, cân bằng dinh dưỡng, tận dụng nguyên liệu giữa các ngày để đỡ phí. Kèm danh sách đi chợ gom theo nhóm (rau, thịt cá, đồ khô) để mình mua một lần cuối tuần.", "url": "thu-vien-prompt.html#p-_thu-vien-them-39"}, {"id": "p-_thu-vien-them-40", "page": "_thu-vien-them", "pageTitle": "Prompt bổ sung", "level": 0, "kind": "prompts", "code": "DS3", "title": "Giúp con học mà không làm hộ", "tags": ["doisong"], "section": "Đời sống & gia đình", "text": "Con mình học lớp [___], đang gặp khó với [môn / dạng bài]. Mình muốn giúp con tự hiểu, không làm hộ.\nBạn đóng vai gia sư kiên nhẫn: giải thích bằng ví dụ gần gũi với trẻ [tuổi], rồi đưa từng câu hỏi gợi mở để con tự tìm ra đáp án. Cho thêm 5 bài luyện từ dễ đến khó. Mình sẽ đọc to cho con nghe, nên viết thật dễ hiểu nhé.", "url": "thu-vien-prompt.html#p-_thu-vien-them-40"}, {"id": "p-_thu-vien-them-41", "page": "_thu-vien-them", "pageTitle": "Prompt bổ sung", "level": 0, "kind": "prompts", "code": "DS4", "title": "Lập ngân sách gia đình", "tags": ["doisong"], "section": "Đời sống & gia đình", "text": "Thu nhập hằng tháng của nhà mình khoảng [___]. Các khoản chi cố định: [___]. Mục tiêu: [tiết kiệm mua nhà / quỹ học cho con / quỹ dự phòng] khoảng [___] trong [thời gian].\nGiúp mình chia ngân sách hằng tháng thành các nhóm hợp lý, chỉ ra khoản nào có thể cắt giảm, và làm một bảng theo dõi đơn giản mình dùng được trên điện thoại. Đây là lập kế hoạch chi tiêu, không cần gợi ý đầu tư.", "url": "thu-vien-prompt.html#p-_thu-vien-them-41"}, {"id": "p-_thu-vien-them-42", "page": "_thu-vien-them", "pageTitle": "Prompt bổ sung", "level": 0, "kind": "prompts", "code": "DS5", "title": "Lời chúc, lời phát biểu", "tags": ["doisong"], "section": "Đời sống & gia đình", "text": "Mình cần [phát biểu ở đám cưới bạn thân / chúc mừng sinh nhật mẹ / chia tay đồng nghiệp nghỉ hưu], dài khoảng [số] phút. Vài kỷ niệm thật: [___]. Mình muốn giọng [xúc động / vui vẻ / trang trọng].\nViết giúp mình 2 phiên bản, câu ngắn để dễ nói, không sáo rỗng. Đánh dấu chỗ nên ngừng lại một chút khi nói.", "url": "thu-vien-prompt.html#p-_thu-vien-them-42"}, {"id": "p-_thu-vien-them-43", "page": "_thu-vien-them", "pageTitle": "Prompt bổ sung", "level": 0, "kind": "prompts", "code": "DS6", "title": "Đọc hiểu giấy tờ cá nhân", "tags": ["doisong"], "section": "Đời sống & gia đình", "text": "Đây là [hợp đồng thuê nhà / điều khoản bảo hiểm / hợp đồng vay] mình sắp ký (đã che tên và số giấy tờ). Giải thích giúp mình bằng lời thường: mình phải làm gì, mất tiền ở những khoản nào, trường hợp nào mình bị thiệt, điều khoản nào nên hỏi lại trước khi ký. Trích nguyên văn điều khoản để mình đối chiếu.", "url": "thu-vien-prompt.html#p-_thu-vien-them-43"}, {"id": "p-_thu-vien-them-44", "page": "_thu-vien-them", "pageTitle": "Prompt bổ sung", "level": 0, "kind": "prompts", "code": "MT1", "title": "Bạn cần biết gì?", "tags": ["meta"], "section": "Hỏi thẳng bạn ấy (meta)", "text": "Mình muốn [việc bạn cần]. Bạn cần biết gì từ mình để làm tốt nhất? Hỏi mình từng câu một, đợi mình trả lời rồi mới hỏi câu tiếp nhé.", "url": "thu-vien-prompt.html#p-_thu-vien-them-44"}, {"id": "p-_thu-vien-them-45", "page": "_thu-vien-them", "pageTitle": "Prompt bổ sung", "level": 0, "kind": "prompts", "code": "MT2", "title": "Viết lại câu nhờ của mình cho tốt hơn", "tags": ["meta"], "section": "Hỏi thẳng bạn ấy (meta)", "text": "Đây là câu mình định nhờ AI: \"[dán câu nhờ]\". Bạn góp ý giúp: còn thiếu bối cảnh gì, chỗ nào dễ hiểu sai, kết quả mình mong đợi đã rõ chưa. Rồi viết lại thành một câu nhờ tốt hơn, giải thích ngắn vì sao tốt hơn.", "url": "thu-vien-prompt.html#p-_thu-vien-them-45"}, {"id": "p-_thu-vien-them-46", "page": "_thu-vien-them", "pageTitle": "Prompt bổ sung", "level": 0, "kind": "prompts", "code": "MT3", "title": "Tự chấm bài theo tiêu chí", "tags": ["meta"], "section": "Hỏi thẳng bạn ấy (meta)", "text": "Trước khi đưa mình bản cuối, tự chấm bài của bạn theo các tiêu chí sau, mỗi tiêu chí điểm 1–10: [đúng mục tiêu / chính xác về số liệu / đúng giọng văn / ngắn gọn / người nhận hành động được ngay]. Tiêu chí nào dưới 8 điểm thì sửa, rồi mới đưa mình bản cuối kèm bảng điểm.", "url": "thu-vien-prompt.html#p-_thu-vien-them-46"}, {"id": "p-_thu-vien-them-47", "page": "_thu-vien-them", "pageTitle": "Prompt bổ sung", "level": 0, "kind": "prompts", "code": "MT4", "title": "Đóng vai người phản biện", "tags": ["meta"], "section": "Hỏi thẳng bạn ấy (meta)", "text": "Bạn đóng vai [luật sư phía đối tác / sếp khó tính / khách hàng khó chiều / kiểm toán viên], đọc bản nháp này và phản biện thẳng thắn: 3 điểm yếu nhất, 3 câu hỏi khó nhất họ sẽ hỏi. Sau đó giúp mình sửa bản nháp để trả lời trước những câu hỏi đó.", "url": "thu-vien-prompt.html#p-_thu-vien-them-47"}, {"id": "p-_thu-vien-them-48", "page": "_thu-vien-them", "pageTitle": "Prompt bổ sung", "level": 0, "kind": "prompts", "code": "MT5", "title": "Có file mà chưa biết nhờ gì", "tags": ["meta"], "section": "Hỏi thẳng bạn ấy (meta)", "text": "Mình có [file / tài liệu / ảnh] này nhưng chưa biết nên nhờ bạn làm gì với nó. Mình làm [nghề], file này dùng để [___]. Bạn xem qua rồi gợi ý 5 việc bạn có thể giúp, việc nào tiết kiệm thời gian nhất cho mình thì đưa lên đầu.", "url": "thu-vien-prompt.html#p-_thu-vien-them-48"}, {"id": "p-_thu-vien-them-49", "page": "_thu-vien-them", "pageTitle": "Prompt bổ sung", "level": 0, "kind": "prompts", "code": "MT6", "title": "Tóm tắt để mở cuộc trò chuyện mới", "tags": ["meta"], "section": "Hỏi thẳng bạn ấy (meta)", "text": "Cuộc trò chuyện này dài quá rồi. Tóm tắt giúp mình mọi thứ quan trọng để mình mở cuộc trò chuyện mới mà không mất mạch: mục tiêu, bối cảnh, những gì đã quyết định, kết quả hiện tại, việc còn dang dở. Viết thành một đoạn để mình copy dán vào cuộc trò chuyện mới.", "url": "thu-vien-prompt.html#p-_thu-vien-them-49"}, {"id": "p-_thu-vien-them-50", "page": "_thu-vien-them", "pageTitle": "Prompt bổ sung", "level": 0, "kind": "prompts", "code": "MT7", "title": "Biến cách làm hôm nay thành hướng dẫn dùng lại", "tags": ["meta"], "section": "Hỏi thẳng bạn ấy (meta)", "text": "Hôm nay mình với bạn đã làm xong [việc] qua cuộc trò chuyện này. Viết giúp mình một bản hướng dẫn để lần sau dán vào Project (hoặc gửi cho đồng nghiệp làm theo): đầu vào cần chuẩn bị, các bước, câu nhờ mẫu cho từng bước, cách kiểm tra kết quả, những lỗi đã gặp và cách tránh.", "url": "thu-vien-prompt.html#p-_thu-vien-them-50"}];window.LESSONS=[{"slug": "cap-1", "level": 1, "title": "Email khó, viết lại trong 30 giây", "how": "Giao như cho đồng nghiệp, rồi nhờ góp ý thẳng", "summary": "Viết email khó trong vài phút bằng cách kể đủ bối cảnh, để bạn ấy hỏi lại, rồi nhờ bạn ấy đóng vai người nhận chê thẳng trước khi gửi.", "time": "20 phút", "tools": "ChatGPT hoặc Claude", "free": "Có", "ntask": 5}, {"slug": "cap-2", "level": 2, "title": "Tài liệu dài, và bẫy “AI bịa”", "how": "Bạn giỏi nhưng đôi khi đoán, nên cứ hỏi “căn cứ đâu?”", "summary": "Tóm tắt hợp đồng dài trong vài phút, tự tay bắt quả tang AI đoán, và tập thói quen hỏi căn cứ cho mọi câu trả lời quan trọng.", "time": "30 phút", "tools": "Claude, ChatGPT · NotebookLM", "free": "Có", "ntask": 6}, {"slug": "cap-3", "level": 3, "title": "Excel lộn xộn thành sạch", "how": "Đưa đống bừa bộn, nhờ sắp xếp", "summary": "Đưa file chi phí 300 dòng lộn xộn, để bạn ấy gợi ý việc cần làm, dọn sạch, phân nhóm, vẽ biểu đồ và tự giải thích cách tính.", "time": "40 phút", "tools": "ChatGPT hoặc Claude", "free": "Một phần", "ntask": 5}, {"slug": "cap-4", "level": 4, "title": "Số liệu thành báo cáo thành slide", "how": "Một cuộc trò chuyện, nhiều thành phẩm", "summary": "Nói tiếp trong cùng một cuộc trò chuyện để biến bảng chi phí đã làm sạch thành báo cáo hợp gu sếp và bộ slide 6 trang.", "time": "30 phút", "tools": "ChatGPT hoặc Claude", "free": "Có", "ntask": 6}, {"slug": "cap-5", "level": 5, "title": "Trợ lý biết nhớ việc", "how": "Dạy bạn ấy một lần, nhờ mãi mãi", "summary": "Để bạn ấy phỏng vấn bạn và tự viết hướng dẫn, tạo trợ lý nhớ mẫu báo cáo. Từ đó chỉ cần dán ghi chú vội.", "time": "30 phút", "tools": "Projects hoặc Gems", "free": "Một phần", "ntask": 6}, {"slug": "cap-6", "level": 6, "title": "Tự tạo công cụ không cần code", "how": "Thiếu công cụ? Nhờ bạn ấy làm luôn", "summary": "Kể vấn đề bằng lời thường, để bạn ấy hỏi lại rồi làm ra một ứng dụng nhỏ chạy được ngay, sửa bằng cách nói chuyện tiếp.", "time": "30–45 phút", "tools": "Claude hoặc ChatGPT", "free": "Có", "ntask": 6}, {"slug": "cap-7", "level": 7, "title": "Giao cả đầu việc cho AI agent", "how": "Giao cả đầu việc, không chỉ giao câu hỏi", "summary": "Giao cho AI agent gom số liệu 5 chi nhánh thành báo cáo quản trị tháng, rồi duyệt kế hoạch và kiểm tra lại.", "time": "45 phút", "tools": "Claude Cowork", "free": "Cần gói trả phí", "ntask": 6}];window.TOPICS=[{"slug": "giong-noi", "title": "Nói thay vì gõ: trò chuyện bằng giọng nói với AI"}, {"slug": "anh-chup", "title": "Chụp ảnh là nhờ được: ảnh, ảnh chụp màn hình, giấy tờ"}, {"slug": "tra-cuu-co-nguon", "title": "Tra cứu có nguồn: tìm kiếm web và nghiên cứu sâu"}, {"slug": "hop-hanh", "title": "Họp nhẹ hơn: từ chuẩn bị đến biên bản và việc cần làm"}, {"slug": "hoc-nhanh", "title": "Học nhanh mọi thứ với một gia sư kiên nhẫn"}, {"slug": "giong-van", "title": "Viết đúng giọng của bạn và của công ty"}, {"slug": "mot-ngay", "title": "Một ngày làm việc cùng AI: bốn nghề, từ sáng đến tối"}];